window.SEITEN={"index.html": "Übersicht", "bilder.html": "Bilder", "auftraege.html": "Aufträge", "entscheidungen.html": "Entscheidungen", "baustellen.html": "Baustellen", "verlauf.html": "Verlauf", "einstieg.html": "Was läuft & Begriffe", "wissen.html": "Wissen", "wissen-fuhrwesen.html": "Wissen: Vom Fuhrwesen", "wissen-meister.html": "Wissen: Vom Meister", "wissen-das-eigene-haus.html": "Wissen: Vom eigenen Haus", "wissen-pacht.html": "Wissen: Von Pacht und Versteigerung", "wissen-leben.html": "Wissen: Vom Leben und Sterben", "wissen-werbung-und-ehe.html": "Wissen: Von Werbung und Ehe", "wissen-geruechte.html": "Wissen: Von Gerüchten und Pamphleten", "wissen-steuern.html": "Wissen: Von Steuern und der Stadtkasse", "wissen-titel-und-aemter.html": "Wissen: Von Titeln und Ämtern", "wissen-schenke.html": "Wissen: Von der Schenke", "wissen-altern-lassen.html": "Wissen: Altern lassen", "wissen-kabinett-und-kanone.html": "Wissen: Vom Kabinett und der Kanone"};
window.SUCHE=[{"p":"bilder.html","i":"i1","x":"Köln von außen Die ganze Stadt mit Mauerring, Häusern und Wald, gebaut aus der Kölner Karte des Originals. Jedes Haus, jeder Turm und jeder Baum steht da, wo das Original ihn hinstellt, auf dem Boden der Karte — die Brücken über dem Fluss. Zum ersten Mal zu sehen am 21.07.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i2","x":"Am Marktstand Ein Klick auf einen der sieben Stände in der Stadt öffnet ihn: links seine Waren mit Kaufpreis oben und Verkaufserlös darunter, rechts die eigenen Karren am Markt, und an der Säule wechselt man zwischen den Ständen — Rohstoffe, Holz & Eisen, Bücher und die übrigen. Zum ersten Mal zu sehen am 13.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i3","x":"Durch die Stadt gehen Ein Klick auf ein Haus in Köln wählt es aus, ein zweiter führt hinein, die rechte Maustaste wieder hinaus — in die eigene Werkstatt, zum Nachbarn, in Kirche und Rathaus. Hier ist es nach Feierabend: Das Rathaus hat zu, und das Spiel sagt es mit den Worten des Originals. Zum ersten Mal zu sehen am 13.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i4","x":"Augsburg Eine zweite Stadt des Originals im selben Nachbau. Gespielt wird Köln; die anderen Städte dienen zum Gegenprüfen, weil sie dieselben Dateien mit anderen Zahlen tragen. Zum ersten Mal zu sehen am 04.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i5","x":"Die Schmiede Ein Handwerksbetrieb von oben, Dach und Decke abgenommen. Im laufenden Spiel gehen die Leute die Arbeitswege, die das Original für diesen Raum vorschreibt. Zum ersten Mal zu sehen am 16.08.2026Die Leute gehen die Arbeitsabläufe des Originals: 17.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i6","x":"Das Labor des Kräuterladens Die rund sechzig Innenräume des Originals stehen im Nachbau, jeder mit seiner ganzen Einrichtung. Zum ersten Mal zu sehen am 06.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i7","x":"Ein Bürger Die Figuren bewegen sich mit den Bewegungen aus den Spieldateien, Bild für Bild wie im Original. Zum ersten Mal zu sehen am 16.08.2026Das Tempo am Original nachgemessen: 23.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i8","x":"Lager erweitern Wie viele Lagerplätze der Betrieb hat, wie groß sie sind und was der nächste kostet. Zum ersten Mal zu sehen am 19.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i9","x":"Verladen und Transportieren Waren aus dem Lager auf den Karren laden: Doppelklick nimmt den ganzen Stapel, Ziehen eine bestimmte Menge — wie im Original. Zum ersten Mal zu sehen am 19.08.2026Mengen ziehen wie im Original: 03.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i10","x":"Der Beutel Ein Klick auf den Geldsack zeigt, was der Spieler bei sich trägt: Tränke, Bücher und andere Gegenstände. Zum ersten Mal zu sehen am 10.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i11","x":"Freie Produktion Die Werkbank: was der Betrieb herstellen kann und welche Zutaten es dafür braucht. Zum ersten Mal zu sehen am 19.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i12","x":"Das Personalbuch Die Belegschaft mit Bildnis, Lehrjahren und Lohn. Wer vier Lehrjahre hat, kann befördert werden. Zum ersten Mal zu sehen am 22.08.2026Entlassen und befördern per Klick aufs Bildnis: 03.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i13","x":"Eine Prämie für alle Jedem Arbeiter eine Prämie zahlen — das Spiel fragt mit denselben Worten wie das Original. Zum ersten Mal zu sehen am 03.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i14","x":"Der Ausbaubaum Welche Einrichtung der Arbeitsraum als Nächstes bekommen kann; jede Kachel ist ein Ausbau aus dem Original. Zum ersten Mal zu sehen am 23.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i15","x":"Was die Ausbauten bringen Mehr Arbeitstempo, weniger Unfälle, Schutz vor Einbrechern — zusammengezählt über alle Ausbauten. Zum ersten Mal zu sehen am 23.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i16","x":"Beim Nachbarn einkaufen Im Betrieb eines anderen kauft man aus seinem Warenlager — nur die fertigen Waren, nicht die Rohstoffe. Zum ersten Mal zu sehen am 23.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i17","x":"Rohstoffe sammeln Der Kräuterladen schickt seine Leute Jasmin und Lavendel suchen, bezahlt mit Arbeitszeit statt mit Geld. Zum ersten Mal zu sehen am 03.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i18","x":"Das Pausemenü Laden, Speichern und die Optionen. Zum ersten Mal zu sehen am 22.08.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i19","x":"Die Grafikoptionen Die Regler des Originals; der Nachbau beginnt mit denselben Werten, die das Spiel bei der Installation setzt. Zum ersten Mal zu sehen am 22.08.2026Die Startwerte der Installation: 03.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i20","x":"Das Bürgerrecht Wer ein Amt will, braucht erst das Bürgerrecht. Hier bietet die Stadt es zum Kauf an. Zum ersten Mal zu sehen am 10.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i21","x":"Das Familiengrab Der Liegeplan des Friedhofs: wer das Grab gemietet hat und bis wann. Von hier aus läßt sich umbetten. Zum ersten Mal zu sehen am 04.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i22","x":"Grabpflege Ein Gehilfe des Friedhofs kann eine Grabstätte pflegen. Zum ersten Mal zu sehen am 03.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i23","x":"Gehilfen verbessern Im Turm des Nekromanten lernt ein Gehilfe ein Talent: Handwerkskunst, Bei Nacht und Nebel oder Rhetorik. Zum ersten Mal zu sehen am 03.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i24","x":"Die Séance In der Krypta: Informationen, eine Schatzkarte oder ein Pakt mit dem Teufel — bezahlt mit Lebenskraft. Zum ersten Mal zu sehen am 04.09.2026Die Knöpfe nennen ihre Kosten: 03.10.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i25","x":"Das Geheimkabinett Wie gründlich die Spione der Gegner aufgespürt werden sollen. Zum ersten Mal zu sehen am 03.09.2026 aufgenommen am 13.10.2026"},{"p":"bilder.html","i":"i26","x":"Die Meisterprüfung Im Arbeitszimmer: das Studium für den nächsten Meistertitel, mit dem man größere Betriebe leiten darf. Zum ersten Mal zu sehen am 04.09.2026 aufgenommen am 13.10.2026"},{"p":"auftraege.html","i":"i27","x":"A1 Die Berufe beim Start ★ Zu tun: das Menü „Wählt nun Euren Beruf“ fotografieren, bevor jemand wählt. offen Foto alle"},{"p":"auftraege.html","i":"i28","x":"A2 Zweimal derselbe Beruf? ★ Zu tun: ausprobieren, ob zwei Spieler denselben Beruf wählen dürfen. offen im Spiel alle"},{"p":"auftraege.html","i":"i29","x":"A5 Die Versteigerung einer Pacht ★ Zu tun: Bargeld zurücklegen, mitbieten und das Bietfenster fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i30","x":"A7 Prozess und Duell unter Menschen ★ Zu tun: wenn es dazu kommt, die Fragen fotografieren und notieren, wann das Spiel wen fragt. offen im Spiel alle"},{"p":"auftraege.html","i":"i31","x":"A8 Köln zu jeder Tageszeit ★ Zu tun: die Stadt im Morgengrauen, mittags, abends und nachts fotografieren, einmal im Sommer und einmal im Winter. offen Foto alle"},{"p":"auftraege.html","i":"i32","x":"A9 Die Werkstatt in Bewegung ★ Zu tun: eine Minute filmen, wie Meister und Gesellen arbeiten. offen Foto alle"},{"p":"auftraege.html","i":"i33","x":"A10 Worüber das Spiel im Netz spricht ★ Zu tun: beim Gastgeber und einem Mitspieler nachsehen, welche Verbindung das Spiel benutzt (die Befehle stehen in der Liste). offen im Spiel Gastgeber"},{"p":"auftraege.html","i":"i34","x":"A12 Wenn die Partie auseinanderläuft ★ Zu tun: Uhrzeit notieren, die Meldung fotografieren und bei allen dreien sofort speichern. offen Spielstand alle"},{"p":"auftraege.html","i":"i35","x":"A13 Wie lange ein Meisterstudium dauert ★ Zu tun: bei jedem neuen Meistergrad die Jahre notieren: Balken voll, Studium begonnen, Grad erreicht. offen im Spiel alle"},{"p":"auftraege.html","i":"i36","x":"A14 Wie lange ein Bau dauert ★ Zu tun: die Baufrage mit Preis fotografieren und notieren, wann das Gebäude fertig war. offen im Spiel alle"},{"p":"auftraege.html","i":"i37","x":"1.1 Der Liegeplan des Friedhofs ★ Zu tun: den Liegeplan und die Fenster hinter seinen drei Knöpfen fotografieren. offen Foto Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i38","x":"1.2 Die Grabkategorien ★ Zu tun: das Fenster „Ein Grab anmieten“ mit der Wahl der Kategorien fotografieren. offen Foto Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i39","x":"1.3 Welches Grab gepflegt wird ★ Zu tun: herausfinden, wie man bei der Grabpflege das Grab auswählt. erfüllt im Spiel Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i40","x":"1.4 Pflegt der Meister von selbst? ★ Zu tun: ein Grab an einen Mitspieler vermieten, einen Meister mit Einmischrecht einstellen und Jahre später zusehen, ob er es pflegen läßt. offen im Spiel Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i41","x":"1.5 Der Pakt mit dem Tod bei Mitspielern ★ Zu tun: einen Gehilfen mit der Versicherung losschicken; der Mitspieler fotografiert das Angebot. offen Foto Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i42","x":"1.6 Sterben mit Versicherungsbulle ★ Zu tun: wenn eine Figur mit Bulle stirbt, die Frage dazu fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i43","x":"1.7 Der Nebel des Grauens ★ Zu tun: den Nebel auf die Werkstatt des Alchimisten legen, für dessen Versuch. offen im Spiel Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i44","x":"1.8 Einen Gehilfen verbessern ★ Zu tun: im Herbst einen Gehilfen auf den Tisch schnallen und halbstündlich seine Sterne notieren. offen im Spiel Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i45","x":"1.9 Altern lassen ★ Zu tun: einen Mitspieler „altern lassen“ und auf beiden Seiten fotografieren. offen Foto Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i46","x":"1.10 Der Teufelspakt ★ Zu tun: in der Séance einen Pakt schließen, nach einer Ablösung suchen und den Einzug drei Jahre später festhalten. offen im Spiel Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i47","x":"1.11 Gibt es Sterbehilfe? ★ Zu tun: am Friedhof nach „Sterbehilfe“ suchen und die Knopfreihen fotografieren. offen Foto Kaldo · Friedhofswärter"},{"p":"auftraege.html","i":"i48","x":"1.12 Welche Berufe man wechseln kann ★ Zu tun: die Liste „Eure Berufe“ fotografieren, bevor gewählt wird. offen Foto alle, beim Wechsel"},{"p":"auftraege.html","i":"i49","x":"1.13 An eine Bank kommen ★ Zu tun: der Wechselstube ein Kaufangebot machen und jeden Schritt fotografieren. offen im Spiel Kaldo · Geldleiher"},{"p":"auftraege.html","i":"i50","x":"1.14 Kredite unter Spielern ★ Zu tun: Zins und Mittel freigeben; ein Mitspieler holt sich einen Kredit, beide fotografieren. offen im Spiel Kaldo · Geldleiher"},{"p":"auftraege.html","i":"i51","x":"1.15 Der Geldbote ★ Zu tun: einen Geldboten losschicken und notieren, wann er zurück ist. offen im Spiel Kaldo · Geldleiher"},{"p":"auftraege.html","i":"i52","x":"2.1 Der Hinweiskasten einer Ware ★ Zu tun: herausfinden, wie er aufgeht, und ihn mit allen Zeilen fotografieren. offen Foto Linus · Alchimist"},{"p":"auftraege.html","i":"i53","x":"2.3 Was das Aufwerten kostet ★ Zu tun: die Frage zum Aufwerten mit Preis fotografieren, einmal zu früh und einmal rechtzeitig. offen Foto Linus · Alchimist"},{"p":"auftraege.html","i":"i54","x":"2.4 Krötenschleim auf ein fremdes Haus ★ Zu tun: Krötenschleim auf das Haus eines Mitspielers anwenden; der fotografiert, was bei ihm geschieht. offen Foto Linus · Alchimist"},{"p":"auftraege.html","i":"i55","x":"2.5 Umziehen ★ Zu tun: ein zweites Haus kaufen und es zum Wohnsitz machen, jeden Schritt fotografieren. offen Foto Linus · Alchimist"},{"p":"auftraege.html","i":"i56","x":"2.7 Das Würfelspiel „17“ ★ Zu tun: als Gast in einer Schänke mit Spieltisch würfeln und Regeln und Tisch fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i57","x":"2.8 Stammtisch und Dunkle Ecke ★ Zu tun: in Gasthaus und Wirtshaus beide Stellen öffnen und fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i58","x":"2.9 Ein Lager für den Gaukler ★ Zu tun: herausfinden, wie man nach dem Wechsel an ein Vagabundenlager kommt. offen im Spiel Linus · Gaukler"},{"p":"auftraege.html","i":"i59","x":"2.10 Die Weidenrute an fremden Betrieben ★ Zu tun: versuchen, sie auf einen fremden Betrieb anzuwenden; der Mitspieler testet sie danach am eigenen. offen Foto Linus · Gaukler"},{"p":"auftraege.html","i":"i60","x":"2.11 Theater und „Kaiserwahl“ ★ Zu tun: im Zirkuszelt beides öffnen, vom Kartenspiel eine Runde filmen. offen Foto Linus · Gaukler"},{"p":"auftraege.html","i":"i61","x":"2.12 Flüche und Voodoopuppe ★ Zu tun: Mitspieler verfluchen und stechen; das Opfer zählt seine Aktionspunkte vorher und nachher. offen im Spiel Linus · Gaukler"},{"p":"auftraege.html","i":"i62","x":"3.1 Wie man einen Betrieb baut ★ Zu tun: ohne Auswahl rechts nach „Bauen“ sehen und den ganzen Weg bis zum Bau fotografieren. offen Foto Luca · Steinmetz"},{"p":"auftraege.html","i":"i63","x":"3.2 Die Knöpfe der Säule ★ Zu tun: die Säule an einem eigenen und einem fremden Haus fotografieren, mit den Menüs dahinter. offen Foto alle"},{"p":"auftraege.html","i":"i64","x":"3.4 Ein Knopf für Arbeitsplätze? ★ Zu tun: im Ausbaufenster nachsehen und fotografieren. offen Foto Luca · Steinmetz"},{"p":"auftraege.html","i":"i65","x":"3.5 Einen Betrieb verkaufen ★ Zu tun: ausschreiben, und ein Mitspieler versucht ihn über das Rathaus zu kaufen; beide fotografieren. offen Foto Luca · Steinmetz"},{"p":"auftraege.html","i":"i66","x":"3.6 Im Steinbruch abbauen ★ Zu tun: die Pacht ersteigern, abbauen und nach Vorkommen suchen, jedes Fenster fotografieren. offen Foto Luca · Steinmetz"},{"p":"auftraege.html","i":"i67","x":"3.7 Rohstoffe veredeln ★ Zu tun: am Steinbruch die Produktionskugel öffnen und fotografieren, mit dem Text unter dem Zeiger. offen Foto Luca · Steinmetz"},{"p":"auftraege.html","i":"i68","x":"3.8 Die Pacht zurückgeben ★ Zu tun: die Stätte an die Stadt verkaufen und den Preis notieren. offen im Spiel Luca · Steinmetz"},{"p":"auftraege.html","i":"i69","x":"3.9 Ein Gesetz ändern ★ Zu tun: mit einem Amt das Fenster „Gesetzesänderung“ fotografieren. offen Foto wer ein Amt hat"},{"p":"auftraege.html","i":"i70","x":"3.10 Das Beweisbuch ★ Zu tun: über „Anklage erheben!“ das Beweisbuch öffnen und fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i71","x":"3.11 Burg, Schloß und Rezeptbuch ★ Zu tun: herausfinden, ob die Burg einen Kanonenturm bekommt, und den Alchimistenvertrag fotografieren. offen Foto wer Edelmann ist"},{"p":"auftraege.html","i":"i72","x":"3.12 Die Kanone ★ Zu tun: Kanonenturm bauen, ausbauen und auf ein Gebäude eines Mitspielers schießen; filmen. offen im Spiel wer ein Schloß hat"},{"p":"auftraege.html","i":"i73","x":"3.13 Das Geheimkabinett ★ Zu tun: bauen und seine vier Stellen bis zur Frage fotografieren. offen Foto wer ein Schloß hat"},{"p":"auftraege.html","i":"i74","x":"3.14 Das Zunfthaus ausbauen ★ Zu tun: als Gildenmeister das Zunfthaus aufwerten und fotografieren. offen Foto Gildenmeister"},{"p":"auftraege.html","i":"i75","x":"3.15 Eine Liebschaft ★ Zu tun: im Musikzimmer des Palazzo eine Liebschaft beginnen, beenden und verfeinden. offen Foto wer Freiherr ist"},{"p":"auftraege.html","i":"i76","x":"3.16 Eine Raubritterfeste ★ Zu tun: herausfinden, wie man an eine Feste und an Räuber kommt. offen im Spiel Luca · Räuber"},{"p":"auftraege.html","i":"i77","x":"3.17 Ein Überfall unter Spielern ★ Zu tun: einen Karren eines Mitspielers belauern und den Kampf auf beiden Seiten filmen. offen im Spiel Luca · Räuber"},{"p":"auftraege.html","i":"i78","x":"3.18 Schutzgeld ★ Zu tun: einem Mitspieler Schutz anbieten; beide fotografieren. offen Foto Luca · Räuber"},{"p":"auftraege.html","i":"i79","x":"N3 Das Marktfenster ★ Zu tun: ein Marktfenster mit mehr als drei eigenen Karren am Markt fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i80","x":"N4 Die Stadtkarte ★ Zu tun: die Karte mit dem Zeiger auf einem fremden Haus fotografieren, eine Sekunde warten, noch einmal. offen Foto alle"},{"p":"auftraege.html","i":"i81","x":"N5 Wichtige Personen ★ Zu tun: in der Personenwahl „Wichtige Personen…“ anklicken und fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i82","x":"N6 Eine Absetzung beantragen ★ Zu tun: bis zur Frage gehen, ohne abzuschicken, und fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i83","x":"N7 Drohbrief und Anschwärzen ★ Zu tun: im eigenen Haus finden, in welchem Raum sie stehen. offen im Spiel alle"},{"p":"auftraege.html","i":"i84","x":"S3 Eine Mehrspielerpartie ★ Zu tun: irgendeinen Stand aus einer Netzwerkpartie schicken, .SRV und .SAV. offen Spielstand alle"},{"p":"auftraege.html","i":"i85","x":"S5 Ein Kanonenturm Zu tun: einen Stand schicken, in dem irgendwo ein Kanonenturm steht. erfüllt Spielstand"},{"p":"auftraege.html","i":"i86","x":"L0 Die Sternskala der Talente ★ Zu tun: eine Figur mit ihren Talentsternen fotografieren (halbe Sterne mit), ihren vollen Namen notieren und gleich danach speichern; zwei Figuren machen es sicher. erfüllt Spielstand"},{"p":"auftraege.html","i":"i87","x":"V1 Macht die Gunst der Arbeiter schneller? ★ Zu tun: Produktionsdauer einer Ware notieren, Prämie zahlen, Dauer erneut notieren — gern mehrmals, bis der Gunstbalken oben ist. erfüllt im Spiel"},{"p":"auftraege.html","i":"i88","x":"V2 Macht ein kranker Arbeiter langsamer? ★ Zu tun: Dauer bei gesunder Belegschaft notieren, warten bis einer erkrankt (oder Krötenschleim), Dauer erneut notieren, ohne ihn zu behandeln. offen im Spiel Linus · Alchimist"},{"p":"auftraege.html","i":"i89","x":"V3 Was tut der Unkendunk wirklich? ★ Zu tun: den Unkendunk auf einen Betrieb anwenden lassen, den ihr beobachten könnt; läuft die Produktion langsamer, obwohl die angezeigte Dauer gleich bleibt?. offen im Spiel Linus · Alchimist"},{"p":"auftraege.html","i":"i90","x":"V4 Die Weidenrute Zu tun: Dauer notieren, die Weidenrute auf den eigenen Betrieb anwenden, Dauer erneut notieren. erfüllt im Spiel"},{"p":"auftraege.html","i":"i91","x":"V5 Beschleunigt die Handwerkskunst? ★ Zu tun: Die bisherigen Zahlen passen, wenn Knochenhammer und Seziermesser zwischendurch gekauft wurden — die Talentwirkung ist darin nicht zu trennen. Bitte: Dauer notieren, einen Talentschritt machen, Dauer erneut notieren, und dazwischen nichts kaufen, keinen Regler im Personalbuch bewegen, keinen Untoten dazuholen. Ein Spielstand direkt danach hilft zusätzl"},{"p":"auftraege.html","i":"i92","x":"V6 Gibt es einen Regler für den Arbeitseifer? Zu tun: im Betriebsfenster nach einem Regler für Tempo, Eifer oder Schichtlänge suchen und fotografieren — auch wenn nichts da ist. erfüllt Foto"},{"p":"auftraege.html","i":"i93","x":"R1 Wie viele Zutatenplätze ein Lager hat Zu tun: im Lager der Goldschmiede zählen, wie viele verschiedene Zutaten Platz haben (die Daten sagen 8, die Erinnerung 5). erfüllt im Spiel"},{"p":"auftraege.html","i":"i94","x":"S1 Eine späte Partie Zu tun: erfüllt durch eine Nürnberger Partie von 1481 und 1505 — mit Erbfolge, vier Schlössern und einer überfüllten Stadt; Kölner Stände ab 1420 bleiben willkommen. erfüllt Spielstand"},{"p":"auftraege.html","i":"i95","x":"S2 Mehrere Stände einer Partie Zu tun: erfüllt durch die Nürnberger Reihe 1405, 1410, 1415. erfüllt Spielstand"},{"p":"auftraege.html","i":"i96","x":"S4 Eine andere Stadt als Köln Zu tun: erfüllt durch Nürnberg; weitere Städte bleiben willkommen. erfüllt Spielstand"},{"p":"auftraege.html","i":"i97","x":"B17 Der Preis auf dem Regalschild ★ Zu tun: das Handelsfenster fotografieren und gleich danach speichern; beides schicken. erfüllt Spielstand"},{"p":"auftraege.html","i":"i98","x":"B58 Der Preis eines fremden Betriebs ★ Zu tun: wie B17, an einem Betrieb, der nicht dir gehört. erfüllt Spielstand"},{"p":"auftraege.html","i":"i99","x":"B45 Das Bild in der Infotafel eines Raumes ★ Laut Programm ist es ein fertiges Bild aus dem Archiv, eines je Gebäudeart. Ob das Foto des Originals genau dieses Bild zeigt, sagt ein Blick darauf. Zu tun: die Infotafel eines Gebäudes öffnen und fotografieren, so dass das Raumbild darin gut zu sehen ist. offen Foto alle"},{"p":"auftraege.html","i":"i100","x":"B46 Welches Bannerwappen dir gehört Zu tun: das Banner fotografieren und gleich danach speichern. erfüllt Spielstand"},{"p":"auftraege.html","i":"i101","x":"B34 Das Personalbuch in anderer Auflösung ★ Das Bild des Buches wird vergrößert, aber sein Rand paßt dann nicht. Ein Foto in einer anderen Auflösung zeigt, ob gestreckt oder beschnitten wird. Zu tun: das Personalbuch in 800 × 600 oder 1024 × 768 fotografieren. offen Foto alle"},{"p":"auftraege.html","i":"i102","x":"B54 Wo ein Handelsfenster steht ★ Bei uns genau in der Mitte. Auf zwei Fotos des Originals stand es etwas rechts unter der Mitte, aber beide Male anders. Zu tun: mehrere Handelsfenster fotografieren, an verschiedenen Gebäuden geöffnet. offen Foto alle"},{"p":"auftraege.html","i":"i103","x":"R2 Wo man Rohstoffe veredelt Zu tun: herausfinden, wie man im Original das Fenster „Rohstoffe veredeln“ öffnet — an welchem Gebäude, über welchen Knopf — und ein Foto davon. erfüllt im Spiel"},{"p":"auftraege.html","i":"i104","x":"B52 Wie man aus Laden und Speichern zurückkommt Zu tun: ausprobieren: Esc, Rechtsklick, etwas anderes?. erfüllt im Spiel"},{"p":"entscheidungen.html","i":"i105","x":"Wo die Karren bewusst anders fahren Ein paar Dinge macht der Nachbau anders als das Original, weil ihm dessen interne Tafeln fehlen: wo ein Karren zuerst einkauft, welche Steuern auf Routenhandel liegen, wie oft die Aufsicht nachsieht. Bleibt das so, oder wird nachgebaut? B60"},{"p":"entscheidungen.html","i":"i106","x":"Wer Rohstoffe sammeln darf Im Original sammelt man nur an den acht Sammelstellen, etwa im Kräutergarten oder auf dem Friedhof. Bei uns darf jedes Gewerk sammeln, das eine sammelbare Zutat braucht — auch die Schänke ihre Gerste und das Waldstück sein Holz. Wie im Original binden, oder der Schänke bewusst das Sammeln lassen? B63"},{"p":"entscheidungen.html","i":"i107","x":"Hochzeitsgebühr und Prämie Die Hochzeitsgebühr und die Prämie für das Zunftmitglied des Jahres gibt es nur im Nachbau; du wolltest beide behalten. Offen ist, wie hoch sie sein sollen — bisher 500 und 1.000 Gulden. B70"},{"p":"entscheidungen.html","i":"i108","x":"Wenn die Stadtkasse leer ist Amtsträger bekommen ihr Einkommen jetzt aus der Stadtkasse, wie in der Tabelle des Originals. Reicht das Geld nicht für alle, zahlt der Nachbau die kleinen Ämter zuerst. Das Original kennt den Fall nicht, weil es das Geld einfach erschafft. So lassen? B71"},{"p":"entscheidungen.html","i":"i109","x":"Welche Steuer ein Betrieb zahlt Im Original zahlt man Gildensteuer oder Umsatzsteuer je nach seinem Gewerk. Im Nachbau kann ein Spieler Betriebe verschiedener Gewerke haben, darum entscheidet es jeder Betrieb für sich. So lassen? B72"},{"p":"entscheidungen.html","i":"i110","x":"Wenn ein Spieler pleitegeht Wer pleite ist, beginnt im Nachbau als neue Dynastie — das hat keine Vorlage im Original. Festzulegen ist, wann genau man als pleite gilt, wohin gepfändete Ware geht (bisher an den Markt) und was die neue Dynastie behält (bisher nur Name, Wappen und Gunst). B74"},{"p":"entscheidungen.html","i":"i111","x":"Prüfungs- und Gehilfengebühren Für die Meisterprüfung und für Gehilfen verlangt der Nachbau Geld: das Erschaffen kostet 2.000, das Verbessern 1.000 und das Füttern 250 Gulden. Das Original nimmt dafür nachweislich nichts. Sollen die Gebühren bleiben oder wegfallen? B80"},{"p":"entscheidungen.html","i":"i112","x":"Die Duelltaktik Im Original wählt man in jeder Kampfrunde neu. Bei uns legt man sie vorher fest, damit eine Netzwerkpartie nicht auf einen Spieler warten muß. Bleibt das so? C44"},{"p":"entscheidungen.html","i":"i113","x":"Entscheidungen im Prozeß Im Original fragt das Spiel jeden im Saal während der Sitzung. Bei uns gibt man seine Entscheidung vorher ab, damit niemand warten muß. Bleibt das so? C52"},{"p":"entscheidungen.html","i":"i114","x":"Der schweigende Mittler Im Original bleibt die Frage offen, bis er antwortet. Bei uns entscheidet er zur nächsten Runde von selbst, damit niemand aufgehalten wird. Bleibt das so? C87"},{"p":"entscheidungen.html","i":"i115","x":"Der Kampf mit Einheiten Im Original ist er ganz gelesen: Echtzeit ohne Runden, höchstens sechs Angreifer, feste Munition. Entschieden ist: Er wird gebaut — aber neu geplant, weil das Original ihn nicht gut umgesetzt hat. Wie er aussehen soll, ist offen. Ideen sind willkommen. C172"},{"p":"entscheidungen.html","i":"i116","x":"Wenn ein Gegenstand zu wenige Opfer findet Der Brief aus Rom und der Moschusduft wirken auf drei Personen. Findet das Original weniger, liest es durch einen Fehler Datenmüll als Person. Der Nachbau wirkt einfach nur auf die gefundenen. Nachbauen lässt sich der Fehler nicht sinnvoll — so lassen? C179"},{"p":"entscheidungen.html","i":"i117","x":"Wie Löhne die Nachfrage heben Im Original gar nicht — die Nachfrage hängt an Einwohnern, Wohnraum und Bauten. Bei uns heben Löhne die Nachfrage ein wenig, als Bremse gegen zu schnell wachsende Vermögen. Weglassen? D3"},{"p":"entscheidungen.html","i":"i118","x":"Punkte, die unter dem Boden liegen Im Original wird ein Punkt, der mehr als 30 neben dem Boden liegt, auf den Boden gesetzt. Der Nachbau vergleicht mit dem Mittel aller Punkte. Vertagt: Hier soll später womöglich ganz neu angesetzt werden. F14"},{"p":"entscheidungen.html","i":"i119","x":"Wie Figuren im Raum laufen Das Original legt über jeden Raum ein Raster von 64 × 64 Feldern; Möbel machen Felder nur teuer, nicht unpassierbar. Der Nachbau nimmt gröbere Felder und sperrt sie ganz. Was wirklich besser ist, ist noch zu klären. Vertagt. F16"},{"p":"entscheidungen.html","i":"i120","x":"Drei Bildvergleiche am Hauptrechner Werkstattabläufe, Meisterbewegungen und die Drehachsen bewegter Gegenstände. Sie werden nebeneinander gerendert, und du wählst, was wie im Original aussieht. Darstellung"},{"p":"entscheidungen.html","i":"i121","x":"Wie die Einwohnerzahl wächst Das Original rechnet die Einwohnerzahl in ganzen Zahlen und Vierteljahresschritten, der Nachbau stufenlos. Der Unterschied ist höchstens gut ein Prozent. Angleichen? Stadt"},{"p":"entscheidungen.html","i":"i122","x":"Klick und Anzeige im Produktionsfenster Gebaut: Ein Klick meldet wie im Original, wenn kein Platz frei ist oder Rohstoffe fehlen, und die Tafel stellt Bedarf und Bestand gegenüber. Bitte am Bild vergleichen. B19"},{"p":"entscheidungen.html","i":"i123","x":"Der Abstand zwischen zwei Knöpfen Gebaut: Der Abstand ergibt sich wie im Original aus der Breite des Feldes und der Zahl der Knöpfe — das erklärt beide Ablesungen, 21 und 8. Bitte am Bild vergleichen. B22"},{"p":"entscheidungen.html","i":"i124","x":"Das kleine Prämienfenster im Personalbuch Gebaut: Es ist die allgemeine Meldungsbox des Spiels, mit einem Zähler von 10 bis zum Bargeld, höchstens 150. Geraten ist nur, dass das Pergament mitwächst — bitte am Bild vergleichen. B40"},{"p":"entscheidungen.html","i":"i125","x":"Wie die Regler anfangs stehen Gebaut: Der Nachbau fängt jetzt mit den Werten an, die der Installer des Originals einträgt — Detailreichtum niedrig, Schatten mittel, Spielgeschwindigkeit 50 %, Maus 64 %. Bitte am Bild vergleichen. B51"},{"p":"entscheidungen.html","i":"i126","x":"Geldsack und Warenkorb im Einkaufsfenster Beides ist jetzt gebaut: Der Warenkorb wirft die eingestellten Mengen weg, und der Geldsack schaltet die Karrenliste auf den Beutel um, aus dem man Gegenstände handeln kann. Du solltest es dir einmal im Bild ansehen, ob es aussieht und sich verhält wie im Original. B55"},{"p":"entscheidungen.html","i":"i127","x":"Wieviel ein Klick auf ein Warenfach kauft Gebaut wie im Original: Ein einfacher Klick ändert nichts, ein Doppelklick nimmt alles, und durch Ziehen stellt man die Stückzahl ein. Beim Nachbarn kaufen geht damit erst, wenn es Beutel und Karren dort gibt. Bitte am Bild vergleichen. B56"},{"p":"entscheidungen.html","i":"i128","x":"Personal verkleinern Gebaut: Ein Klick auf ein Bildnis im Personalbuch zeigt „entlassen!“ und „befördern!“ wie im Original, und es geht genau die angeklickte Person. Geraten ist nur, wo die beiden Zeilen stehen — bitte am Bild vergleichen. C134"},{"p":"entscheidungen.html","i":"i129","x":"Wann es hell wird Neu: Draußen in Köln geht der Tag jetzt wie im Original — morgens kühl und blau, mittags warm und hell, abends bernsteinfarben, nachts dunkelblau, und je nach Jahreszeit früher oder später. Die Sonne wandert und färbt sich, die Laternen gehen abends nacheinander an und morgens wieder aus, und die Häuser leuchten nicht mehr von selbst. Bitte am Bild vergleichen. In den Räumen dämm"},{"p":"entscheidungen.html","i":"i130","x":"Das Bürgerrecht im Rathaus kaufen Gebaut: Im Rathaus gibt es jetzt die Stelle, an der man das Bürgerrecht kauft, wie im Original nur, wenn es einem angeboten wird. Du solltest es dir einmal im Bild ansehen. F29"},{"p":"entscheidungen.html","i":"i131","x":"Berserkerwut und Eifersucht Entschieden und gebaut: genau wie im Original — auch dort, wo das Original seltsam wirkt. Die Berserkerwut verärgert den Hausherrn fast nie, und die Eifersucht macht ihr Opfer bei drei Amtsträgern beliebter. Das wird später im Spiel angesehen und neu bewertet, ob es sich richtig anfühlt. F33"},{"p":"entscheidungen.html","i":"i132","x":"Vier Handgriffe ohne Vorbild Vier Dinge, die der Nachbau zusätzlich konnte, sind gestrichen, weil das Original sie nicht hat: die Sterbehilfe, das vorzeitige Ablösen des Teufelspakts, das Einrichten von Arbeitsplätzen (im Original stehen alle Plätze eines Hauses offen) und ein eigener Steuerbefehl (die Steuer setzt man wie im Original über einen Gesetzesantrag). 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i133","x":"Einen Betrieb gründen Ein neuer Betrieb entsteht wie im Original über das Baumenü auf einem freien Bauplatz der Stadt, nicht mehr nur durch Wahl einer Ware. Auch einen Friedhof kauft man so. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i134","x":"Die Versteigerung einer Pacht Wer auf ein Waldstück, einen Steinbruch oder eine Mine bietet, tut das wie im Original in einer kleinen Filmszene mit den anderen Bietern, nicht nur über ein Fenster. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i135","x":"Das eigene Haus auf der Karte Jeder Spieler beginnt wie im Original mit einem Wohnhaus, das in der Stadt steht. Daran hängen das Umziehen, das Aufwerten des Wohnhauses und später die Räume — mit ihnen das Geheimkabinett, der Kanonenturm und die Geliebte. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i136","x":"Die Versicherung gegen den Tod Die Versicherung des Friedhofs wird wie im Original verkauft: Der Gehilfe des Friedhofswärters geht durch die Stadt und bietet sie an, und ein Spieler bekommt das Angebot, statt sie selbst zu kaufen. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i137","x":"Geld aus Wundern Wenn der Erzbischof ein Wunder wirkt, zahlen Madonna und Goldregen ihr Geld wie im Original aus dem Nichts: Die Wallfahrer kommen von außerhalb, und die Münzen fallen vom Himmel. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i138","x":"Einen Betrieb verkaufen Wer einen Betrieb verkaufen will, schreibt ihn wie im Original beim Rathaus zu einem selbst gewählten Preis aus und wartet auf einen Käufer, statt ihn sofort zu Geld zu machen. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i139","x":"Die Preise des Geheimkabinetts Der Attentäter verlangt, was er im Original verlangt: fürs Vergiften kein Geld, nur Aktionspunkte nach dem Amt des Opfers; für die anderen Aufträge einen Anteil am Vermögen. Die vier Fenster mit ihrem Regler sind dazu gebaut. 16.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i140","x":"Der Geldverleiher Der Geldverleiher wird ein ganzer Beruf wie im Original: die Bank als Betrieb, Kredite, sieben Währungen mit Geldwechsel und Geldbote, und auch die Computergegner leihen sich Geld. 15.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i141","x":"Ohne Stadtchronik Gespielt wird wie im Original im Modus „Ohne historische Nachrichten“, so wie du das Original spielst: Die Stadtchronik mit ihren festen Ereignissen läuft nicht mit. Gebaut bleibt sie trotzdem. 15.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i142","x":"Den Stammtisch verlassen Im Original steht der Knopf „verlassen“ im Fenster, tut aber nichts. Im Nachbau kann man einen Stammtisch wirklich verlassen. 15.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i143","x":"Ketzerei-Akten Wer im falschen Glauben lebt, wird nur alle vier Jahre aktenkundig, und das trifft Computergegner, ihre Familien und die Bürger — nie einen Spieler. 14.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i144","x":"Ämter ohne Amtszeit Ein Wahlamt hat keine feste Amtszeit. Es wird frei, wenn der Inhaber stirbt, abgesetzt wird, zurücktritt oder aufsteigt. 14.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i145","x":"Der eigene Betrieb steht in der Stadt Wer als Spieler beitritt, übernimmt das Haus seiner Werkstattfamilie in Köln, das beim Spielbeginn ein Computergegner bekommen hatte — im Original suchen sich die Spieler ihre Häuser zuerst aus. So findet man die eigene Werkstatt in der Stadt und kann sie per Klick betreten. 13.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i146","x":"Hochzeitsgebühr und Prämie bleiben Beide gibt es im Original nicht. Der Nachbau behält sie; wie hoch sie sein sollen, ist noch offen. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i147","x":"Baurabatt für Kämmerer und Baumeister Im Original bekommt ihn nur der Kämmerer, obwohl der Text ihn auch dem Baumeister verspricht. Im Nachbau bauen beide 15 Prozent billiger. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i148","x":"Ausbaupreise mit dem Baupreisniveau Im Original hängt der Preis eines Ausbaus nicht am Baupreisniveau der Stadt. Im Nachbau spielt es weiter mit. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i149","x":"Pleite heißt Neustart Erst wird gepfändet wie im Original. Reicht das nicht, beginnt der Spieler in derselben Partie als neue Dynastie, statt auszuscheiden — damit eine Partie mit mehreren Spielern nicht zerbricht. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i150","x":"Im Nachbau verschwindet kein Geld Wo das Original Geld einfach vernichtet oder aus dem Nichts erschafft, hat der Nachbau eine Kasse — die Stadt wirtschaftet wie jeder andere. Die Stadtkasse wird auch nicht aufgefüllt, wenn sie leer ist. 08.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i151","x":"Berserkerwut und Eifersucht Beide wirken genau wie im Original, auch wo es seltsam wirkt. Später im Spiel wird neu bewertet, ob es sich richtig anfühlt. 08.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i152","x":"Der Unkendung wirkt immer Im Original wirkt er nur, wenn er zufällig an erster Stelle im Bestand der Welt liegt — oft also gar nicht. Im Nachbau halbiert er jedes Mal. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i153","x":"Wo die Warmen Socken wirken Im Original wirken sie an einer etwas anderen Auswahl von Gebäuden. Im Nachbau genau an den fünf, in denen gesammelt wird. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i154","x":"Ein Grab umbetten Pauschal 500 Gulden; der Friedhofsbesitzer verlegt kostenlos. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i155","x":"Gildensteuer erst mit Zunfthaus Gildensteuer zahlt erst, wessen Zunft ein Zunfthaus hat; davor Umsatzsteuer. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i156","x":"Anwärter für die Reichsämter Computerfiguren bewerben sich mit, damit die Ämter besetzt bleiben und der Aufstieg ein Wettbewerb ist. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i157","x":"Meldungen zum Teufelspakt Das Original sagt nichts an. Der Nachbau bestätigt die Rückzahlung, mahnt im letzten Jahr und kündigt das Unglück an. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i158","x":"Der Glaube der Heiratskandidatinnen Kandidatinnen sind ganze Personen mit eigenem Glauben, der für sie zählt. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i159","x":"Den Wohnsitz ausbauen Welche Ausbauten ein Haus bekommen kann, hängt an der Hausart; sie gehören zum Gebäude als Ganzem. 07.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i160","x":"Der Termin der Hochzeit Die Trauung wird eine Runde vorher angekündigt, damit jeder Gast antworten kann. Im Original ist sie meist zwei Stunden nach der Verlobung. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i161","x":"Wer bei der Hochzeit traut Im Original steht dort eine Statistenfigur. Im Nachbau traut ein Amtsträger, mit Segensfrage und Einwänden. 07.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i162","x":"Den Glauben wechseln Nur als Umtaufe in einer Kirche, gegen Geld an deren Besitzer. 06.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i163","x":"Ausbauten gehören zum Haus Ausbauten hängen am Gebäude, nicht am Besitzer: Wer umzieht, lässt sie zurück. 06.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i164","x":"Kein Schwierigkeitsgrad Der Nachbau hat keinen Regler für den Schwierigkeitsgrad und spielt fest auf „Normal“. 04.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i165","x":"Titel für das Geheimkabinett Das Geheimkabinett verlangt den Edelmann. 04.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i166","x":"Original-Spielstände laden Original- Spielstände müssen im Nachbau nicht geladen werden können. Sie dienen weiter als Messgerät. 04.10.2026 · ohne Vorlage"},{"p":"entscheidungen.html","i":"i167","x":"Text in Meldungen Blocksatz und gleich breite Knöpfe, wie im Original. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i168","x":"Der Zierat über Fenstern Schwarz, so wie man ihn aus dem Original kennt. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i169","x":"Kampf mit Einheiten Der Einheitenkampf wird gebaut, aber neu geplant, weil er im Original nicht gut umgesetzt ist. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i170","x":"Jede Kirche hat ihren Gottesdienst Im Original bekommen manche Kirchen durch einen Fehler nie einen Gottesdienst. Der Nachbau baut ihn nach und behebt den Fehler. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i171","x":"Computergegner wachsen ohne Grenze Im Original hören die Gegner um 1460 auf zu wachsen. Im Nachbau wollen sie aus Eigeninteresse immer weiter wachsen, wie der Spieler. 03.10.2026 · bewusst anders"},{"p":"entscheidungen.html","i":"i172","x":"Computergegner bauen aus Die Gegner bauen ihre Betriebe aus und ziehen in größere Häuser. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i173","x":"Baupreise Gebäude kosten, was sie im Original kosten. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i174","x":"Pleite der Computergegner Auch Computergegner können pleitegehen. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i175","x":"Die Verlängerung eines Grabes Wer die Verlängerung ablehnt oder nicht antwortet, gibt das Grab zurück. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i176","x":"Die Grabmiete Die Miete richtet sich nach Vermögen und Grabart, und der Friedhof behält seinen gemessenen Anteil. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i177","x":"Beutel statt Warenlager Der Spieler trägt nur den Beutel mit Gegenständen; Waren liegen in Betrieben und auf Karren. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i178","x":"Der Partiebeginn Jeder Betrieb gehört zu Beginn jemandem; die freien bekommen Computergegner mit 3.000 Gulden. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i179","x":"Die Startwerte der Regler Der Nachbau beginnt mit den Werten, die der Installer des Originals einträgt. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i180","x":"Das Wappen Das Wappen gehört zur Dynastie, nicht zur Spielernummer. 03.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i181","x":"Personal entlassen Man entlässt genau die Person, die man anklickt. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i182","x":"Die Anfangstalente Talente kommen aus dem Beruf oder aus dem Stammbaum, wie bei der Charaktererstellung des Originals. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i183","x":"Das Bürgerrecht kaufen Bürger wird man durch Kauf im Rathaus, nicht allein durch Vermögen. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i184","x":"Handelsrouten statt Dauerauftrag Der Dauerauftrag des Nachbaus fällt; an seine Stelle treten Handelsrouten und der Meisterauftrag wie im Original. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i185","x":"Wie Karren Rohstoffe nachkaufen Nachgekauft wird nach der Regel des Originals. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i186","x":"Das Lange Kanonenrohr Der Nachbau bietet das Lange Rohr am Kanonenturm an, mit der gemessenen Wirkung auf die Reichweite. 02.10.2026 · wie im Original"},{"p":"entscheidungen.html","i":"i187","x":"Große Bildschirme Das Original kennt nur drei kleine Auflösungen. Auf breiten Bildschirmen wächst die Oberfläche im Nachbau mit. vor Oktober · ohne Vorlage"},{"p":"entscheidungen.html","i":"i188","x":"Der Markt als ein Gebäude Im Original läuft man die sieben Marktstände einzeln ab. Im Nachbau ist der Markt ein Gebäude, und die Stände sind Reiter darin — welche Ware wo liegt, ist wie im Original. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i189","x":"Einfachere Einrichtung der Betriebe Im Original hat fast jeder Einrichtungsgegenstand eigene Voraussetzungen. Der Nachbau fasst sie zu Ausbaustufen zusammen. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i190","x":"Nur eine Währung Das Original führt sieben Stadtwährungen mit Wechselkursen. Der Nachbau rechnet überall in Gulden. vor Oktober · bewusst anders"},{"p":"entscheidungen.html","i":"i191","x":"Nur eine Währung Das Original führt sieben Stadtwährungen mit Wechselkursen. Der Nachbau rechnet überall in Gulden. vor Oktober"},{"p":"entscheidungen.html","i":"i192","x":"Einfachere Einrichtung der Betriebe Im Original hat fast jeder Einrichtungsgegenstand eigene Voraussetzungen. Der Nachbau fasst sie zu Ausbaustufen zusammen. vor Oktober"},{"p":"entscheidungen.html","i":"i193","x":"Der Markt als ein Gebäude Im Original läuft man die sieben Marktstände einzeln ab. Im Nachbau ist der Markt ein Gebäude, und die Stände sind Reiter darin — welche Ware wo liegt, ist wie im Original. vor Oktober"},{"p":"entscheidungen.html","i":"i194","x":"Computergegner wachsen ohne Grenze Im Original hören die Gegner um 1460 auf zu wachsen. Im Nachbau wollen sie aus Eigeninteresse immer weiter wachsen, wie der Spieler. 03.10.2026"},{"p":"entscheidungen.html","i":"i195","x":"Jede Kirche hat ihren Gottesdienst Im Original bekommen manche Kirchen durch einen Fehler nie einen Gottesdienst. Der Nachbau baut ihn nach und behebt den Fehler. 03.10.2026"},{"p":"entscheidungen.html","i":"i196","x":"Kampf mit Einheiten Der Einheitenkampf wird gebaut, aber neu geplant, weil er im Original nicht gut umgesetzt ist. 03.10.2026"},{"p":"entscheidungen.html","i":"i197","x":"Kein Schwierigkeitsgrad Der Nachbau hat keinen Regler für den Schwierigkeitsgrad und spielt fest auf „Normal“. 04.10.2026"},{"p":"entscheidungen.html","i":"i198","x":"Wer bei der Hochzeit traut Im Original steht dort eine Statistenfigur. Im Nachbau traut ein Amtsträger, mit Segensfrage und Einwänden. 07.10.2026"},{"p":"entscheidungen.html","i":"i199","x":"Der Termin der Hochzeit Die Trauung wird eine Runde vorher angekündigt, damit jeder Gast antworten kann. Im Original ist sie meist zwei Stunden nach der Verlobung. 07.10.2026"},{"p":"entscheidungen.html","i":"i200","x":"Meldungen zum Teufelspakt Das Original sagt nichts an. Der Nachbau bestätigt die Rückzahlung, mahnt im letzten Jahr und kündigt das Unglück an. 07.10.2026"},{"p":"entscheidungen.html","i":"i201","x":"Wo die Warmen Socken wirken Im Original wirken sie an einer etwas anderen Auswahl von Gebäuden. Im Nachbau genau an den fünf, in denen gesammelt wird. 07.10.2026"},{"p":"entscheidungen.html","i":"i202","x":"Der Unkendung wirkt immer Im Original wirkt er nur, wenn er zufällig an erster Stelle im Bestand der Welt liegt — oft also gar nicht. Im Nachbau halbiert er jedes Mal. 07.10.2026"},{"p":"entscheidungen.html","i":"i203","x":"Im Nachbau verschwindet kein Geld Wo das Original Geld einfach vernichtet oder aus dem Nichts erschafft, hat der Nachbau eine Kasse — die Stadt wirtschaftet wie jeder andere. Die Stadtkasse wird auch nicht aufgefüllt, wenn sie leer ist. 08.10.2026"},{"p":"entscheidungen.html","i":"i204","x":"Pleite heißt Neustart Erst wird gepfändet wie im Original. Reicht das nicht, beginnt der Spieler in derselben Partie als neue Dynastie, statt auszuscheiden — damit eine Partie mit mehreren Spielern nicht zerbricht. 08.10.2026"},{"p":"entscheidungen.html","i":"i205","x":"Ausbaupreise mit dem Baupreisniveau Im Original hängt der Preis eines Ausbaus nicht am Baupreisniveau der Stadt. Im Nachbau spielt es weiter mit. 08.10.2026"},{"p":"entscheidungen.html","i":"i206","x":"Baurabatt für Kämmerer und Baumeister Im Original bekommt ihn nur der Kämmerer, obwohl der Text ihn auch dem Baumeister verspricht. Im Nachbau bauen beide 15 Prozent billiger. 08.10.2026"},{"p":"entscheidungen.html","i":"i207","x":"Hochzeitsgebühr und Prämie bleiben Beide gibt es im Original nicht. Der Nachbau behält sie; wie hoch sie sein sollen, ist noch offen. 08.10.2026"},{"p":"entscheidungen.html","i":"i208","x":"Den Stammtisch verlassen Im Original steht der Knopf „verlassen“ im Fenster, tut aber nichts. Im Nachbau kann man einen Stammtisch wirklich verlassen. 15.10.2026"},{"p":"baustellen.html","i":"i279","x":"Einen Betrieb gründen"},{"p":"baustellen.html","i":"i280","x":"Bei der Versteigerung einer Pacht bieten"},{"p":"baustellen.html","i":"i281","x":"Einen Friedhof kaufen"},{"p":"baustellen.html","i":"i282","x":"Das Geheimkabinett bauen"},{"p":"baustellen.html","i":"i283","x":"In ein anderes Haus umziehen"},{"p":"baustellen.html","i":"i284","x":"Eine Kanone bauen"},{"p":"baustellen.html","i":"i285","x":"Die Kanone ausbauen"},{"p":"baustellen.html","i":"i286","x":"Die Kanone abfeuern"},{"p":"baustellen.html","i":"i209","x":"Wie die Nachfrage mit der Stadt wächst Im Original wächst die Nachfrage mit Einwohnern, Wohnraum und Ausbau der Stadt. Die Häuser der Stadt und ihre Einwohner gibt es im Nachbau inzwischen, und für den Zuzug neuer Leute wird die Rechnung schon benutzt. Für die Nachfrage fehlen noch zwei kleinere Zutaten aus den Spieldaten; bis dahin bleibt sie fest. A10"},{"p":"baustellen.html","i":"i210","x":"Was der erste Betrieb herstellt Im Original wählt man zu Beginn einen Beruf, sein Wappen und sein Gesicht. Der Nachbau verteilt die Waren noch reihum, und Wappen und Gesicht werden zugeteilt. B7"},{"p":"baustellen.html","i":"i211","x":"Was die Regler in den Optionen tun Inzwischen gelesen: Jeder sichtbare Regler wirkt, etwa auf die Schatten oder die Mausgeschwindigkeit. Der Nachbau merkt sich bisher nur ihre Stellung; es fehlt der Bau. B49"},{"p":"baustellen.html","i":"i212","x":"Was der Unkendung genau tut Der Unkendung bremst einen fremden Betrieb für drei Stunden auf halbe Kraft und schickt die Hälfte der Arbeiter nach Hause, und erst am nächsten Morgen kommen sie wieder — das ist gelesen und gebaut. Noch vereinfacht: Bei uns hat jeder Arbeiter eine Wohnung, und die drei Stunden laufen auf der Spieluhr; beides klärt sich mit der echten Bevölkerung. Im Bild fehlen noch W"},{"p":"baustellen.html","i":"i213","x":"Wie die Partie aus der Karte beginnt Die Partie beginnt jetzt mit den Gebäuden der Kölner Karte, verteilt auf die Dynastien wie im Original, und der Meister wählt seine Ware um 8 und 13 Uhr neu. Noch geschätzt ist, welche Dynastie welches Gebäude bekommt. Wer als Spieler beitritt, übernimmt seit dem 13.10.2026 das Haus seiner Werkstattfamilie. B66"},{"p":"baustellen.html","i":"i214","x":"Das erste Haus Wer im Nachbau noch keinen Wohnsitz hat, bezieht sein erstes Haus sofort. Im Original hat jede Dynastie von Anfang an eins; das kommt, wenn der Spieler mit einem Haus der Karte beginnt. B68"},{"p":"baustellen.html","i":"i215","x":"Wie man um eine Pacht bietet Die Versteigerung einer Pacht ist jetzt gebaut, mit den gemessenen Regeln des Originals. Weil die Szene mit Schieberegler noch fehlt, bietet man vorerst mit einem Befehl, und jede Runde dauert höchstens eine halbe Spielstunde. Ein paar Randfälle sind geschätzt, etwa was passiert, wenn in der letzten Runde keiner mehr bietet. B76"},{"p":"baustellen.html","i":"i216","x":"Wo ein gekaufter Ausbau steht Kauft man einen Ausbau, merkt sich der Nachbau nur, dass er da ist, nicht in welchem Raum er steht, und jedes Stück gilt als neu. Im Original hat jedes Stück seinen Platz und seinen Zustand. Für den Wert des Hauses macht das fast nie einen Unterschied. B77"},{"p":"baustellen.html","i":"i217","x":"Wie das Vermögen gezählt wird Das Vermögen rechnet jetzt wie im Original: Bargeld plus der Wert der Häuser und Waren. Geschätzt ist zweierlei: Jede Ware zählt bei uns einmal, im Original je Stapel im Lager. Und Häuser zählen immer als neu, weil sie bei uns noch nicht verfallen. B78"},{"p":"baustellen.html","i":"i218","x":"Talente beim Spielbeginn Jede Figur hat jetzt eigene Talente wie im Original, und ein neu eingestellter Meister hat wie dort den ersten Grad. Vorläufig gesetzt bleibt, was erst mit dem Spielbeginn-Menü und der echten Stadtbevölkerung kommt: wie stark die Computergegner sind, wie die Heiratskandidatinnen begabt sind, und dass manche vornehme Figuren neu angelegt statt aus der Stadt genommen werden "},{"p":"baustellen.html","i":"i219","x":"Wenn Computergegner aufsteigen Die Computergegner steigen jetzt wie im Original von selbst auf, bauen aus, ziehen in bessere Häuser, tragen Titel und zahlen beim Bauen die Preise der Stadt wie ein Spieler. Vorläufig gesetzt ist: in welcher Reihenfolge sie das überlegen, dass die Spieler davon keine Nachricht bekommen, wie der Titel vererbt wird, dass ihre Bauten ohne Bauzeit sofort stehen, und das"},{"p":"baustellen.html","i":"i220","x":"Wie schnell man zur Meisterprüfung kommt Wie lange man auf die Zulassung zur Prüfung wartet, hängt von einem Talent ab. Seit dem 16. Oktober ist das Rätsel gelöst: Es zählt das eigene Talent, aber nie weniger als ein Viertel, und der Aufstieg kommt erst zu Beginn der nächsten Runde. Das trifft alle 17 Fälle in den Spielständen. Der Nachbau rechnet noch mit einem festen Viertel und läßt in derselbe"},{"p":"baustellen.html","i":"i221","x":"Die Erstausstattung Zu Spielbeginn schenkt das Original Zutaten für 500 Gulden; das ist jetzt gebaut. Geschätzt ist dabei: Jedes Lager beginnt klein, die Preise werden jedes Mal frisch gerechnet, und alle Zutaten kommen in ein gemeinsames Rohstofflager. Das ändert sich, wenn das Lager wie im Original Plätze für jede Ware bekommt. B85"},{"p":"baustellen.html","i":"i222","x":"Wie das Zunfthaus entsteht Wie im Original baut die Stadt ein Zunfthaus, sobald ein Gewerk drei Betriebe hat, und erst dann gibt es Gildensteuer und einen Gildenmeister. Vorläufig steht das Haus beim nächsten Rundenbeginn sofort fertig da, ohne Bauzeit und ohne eigenen Platz in der Stadt, und nur in der ersten Stufe. Das ändert sich, wenn die Stadt echte Gebäude baut. B87"},{"p":"baustellen.html","i":"i223","x":"Der Gehilfe aus der Leiche Am Friedhof kann man jetzt wie im Original aus einem Toten einen Gehilfen machen, und auf dem Friedhof liegen auch erfundene Tote. Vorläufig gesetzt ist: Der Gehilfe hat nur drei der fünf Talente, die Reihenfolge der Gräber ist fest statt frei wählbar, und Titel, Beruf und Bild der erfundenen Toten werden nicht gespeichert. Im Bild kann man noch keine Leiche auswählen. B"},{"p":"baustellen.html","i":"i224","x":"Der Geldsack im Transportfenster Im Transportfenster kann man jetzt wie im Original über den Geldsack Gegenstände aus dem Beutel handeln, und alle Fragen dazu sind nachgelesen und gebaut. Seit dem 16. Oktober ist auch die Lage der Überschrift „Gegenstände handeln“ gelesen: Sie sitzt dicht unter dem Streifen, nicht in seiner Mitte; der Nachbau setzt sie noch sechs Punkte zu tief. B90"},{"p":"baustellen.html","i":"i225","x":"Wie hell die Bilder der Oberfläche stehen Inzwischen gelesen: Das Original dunkelt die Bilder der Oberfläche leicht ab und hellt sie auf, wenn man mit der Maus darüberfährt. Der Nachbau zeigt sie überall voll hell. Umgebaut wird das am Hauptrechner, weil es jedes Bild verändert und nur dort die Bilder verglichen werden können. B91"},{"p":"baustellen.html","i":"i226","x":"Der Lohn des Meisters, im Einzelnen Der Meister bekommt jetzt den Lohn seiner Gruppe wie im Original, und auch geklärt ist, warum viele Meister wie Gesellen bezahlt werden: Das Spiel befördert jeden mit dem Handwerk eines Lehrlings nach vier Dienstjahren, auch den Meister. Vorläufig gesetzt sind Kleinigkeiten, etwa dass die Beförderung sofort wirkt und nicht erst, wenn er den Betrieb betritt. B92"},{"p":"baustellen.html","i":"i227","x":"Jemandem Furcht einflößen Umgebaut wie im Original: Furcht einflößen ist ein Vorrecht ab dem Titel Patrizier, kostet zwei Aktionspunkte und kein Geld und hindert das Opfer einen Tag lang nur daran, Euch zu sabotieren oder verprügeln zu lassen. Seit dem 15. Oktober wählt man sie wie im Original im Fenster „Eure Privilegien“, nicht mehr bei der finsteren Gestalt im Hinterzimmer. Vorläufig bleiben ei"},{"p":"baustellen.html","i":"i228","x":"Die Räume im Wohnhaus Im Original hat ein Wohnhaus je nach Größe ein bis drei Räume wie Hinterzimmer, Bibliothek oder Salon. Die Räume selbst sind jetzt gebaut. Seit dem 16. Oktober gibt es auch das Fenster „Räume“ zum Ausbau des Hauses, und das Arbeitszimmer steht wie im Original in jedem Wohnhaus von selbst. Offen ist, dass manche Handlungen nur im passenden Raum gehen und dass auch die Computer"},{"p":"baustellen.html","i":"i229","x":"Der Handel am Markt Neu im Bild: Ein Klick auf einen der sieben Marktstände in der Stadt öffnet ihn, rechts an der Säule wechselt man zwischen den Ständen, links stehen die Waren mit Kauf- und Verkaufspreis, und gehandelt wird mit den eigenen Karren, die am Markt stehen. Vorläufig ist einiges geschätzt: wie viele Fächer ein Stand hat, und dass nur drei Karren in der Liste stehen. Der Markt hat übr"},{"p":"baustellen.html","i":"i230","x":"Durch die Stadt gehen Neu: Ein Klick auf ein Haus in Köln wählt es aus, ein zweiter Klick führt hinein, die rechte Maustaste wieder hinaus — wie im Original. Hinein darf man in die eigene Werkstatt, zu den Nachbarn, in Kirche und Rathaus; fremde Wohnhäuser bleiben zu, und nach Ladenschluss heißt es „Geschlossen!“. Seit die Stadt so steht wie im Original, liegt jedes Haus genau dort, wo sein Gebäud"},{"p":"baustellen.html","i":"i231","x":"Boden und Licht der Stadt Neu: Der Boden Kölns trägt seine Originalbilder — Wiese, Weg, Acker — und das Licht der Stadt rechnet wie im Original. Ein paar Kleinigkeiten waren dabei vorläufig gesetzt; seit dem 16. Oktober sind die meisten gelesen: Zwei Bodenarten am Rand werden zusammengezählt, nicht übereinandergelegt, bei der Wahl der Laternen liegt einer der neun Meßpunkte etwas näher, und die La"},{"p":"baustellen.html","i":"i232","x":"Brand, Pest und Sturm Neu: Wie im Original kann die Stadt von einer Katastrophe getroffen werden — einem Wirbelsturm, einem Großbrand oder der Pest. Ein Würfel entscheidet zu Beginn jedes Jahres, auf der Schwierigkeit „Normal\" etwa alle fünf bis sechs Jahre, und die Stadtchronik schickt sie außerdem zu festen Jahren. Der Sturm bringt drei Stunden Unwetter mit Blitzen. Beim Großbrand springt das Fe"},{"p":"baustellen.html","i":"i233","x":"Wohnung und Geld der Arbeiter Neu: Jeder Arbeiter hat jetzt eine Wohnung und sein eigenes Geld. Beim Einstellen sucht er sich die Arbeiterunterkunft, die seiner Werkstatt am nächsten liegt; wer keinen Platz findet, zieht nachmittags ein, sobald einer frei wird. Lohn und Handgeld landen bei ihm, und die Miete zahlt er selbst an die Stadt. Neu dazu: Wer entlassen wird, bleibt als Arbeitsloser in der"},{"p":"baustellen.html","i":"i234","x":"Leute auf der Straße Neu: Die Arbeiter gehen jetzt sichtbar durch Köln. Wie im Original kommen die Leute der Spieler morgens ohne Weg in die Werkstatt, abends gehen sie alle zugleich zu Fuß heim, die Leute der Konkurrenz einer nach dem anderen; morgens gehen nur diese zu Fuß zur Arbeit. Den Weg sucht der Nachbau wie das Original über ein Raster der Stadt, das bevorzugt die Mitte der Wege nimmt. Vo"},{"p":"baustellen.html","i":"i235","x":"Jeder Arbeiter ein ganzer Mensch Neu: Jeder Angestellte ist jetzt ein vollständiger Mensch mit Geschlecht, Alter und Lebenszeit — wie die Familienmitglieder. Er sieht aus wie im Original: Sein Beruf und sein Geschlecht bestimmen die Figur, und sein Gesicht im Personalbuch ist genau der Kopf, den seine Figur in der Werkstatt und auf der Straße trägt. In Handwerken, die das Original nur Männern gibt"},{"p":"baustellen.html","i":"i236","x":"Die Stadt ist bewohnt Neu: In Köln leben jetzt Menschen, die weder Spieler noch Konkurrenten noch Angestellte sind — wie im Original. Zu Spielbeginn sind alle dreißig Sitze im Rathaus und in der Kirche besetzt, teils mit den Herren der Häuser, teils mit Bürgern; viele Amtsträger sind miteinander verheiratet und haben Kinder, dazu kommen sechzehn junge Leute. Wer ein Amt hat, bekommt sein Einkommen"},{"p":"baustellen.html","i":"i237","x":"Der Gottesdienst Neu: Wer eine Kirche besitzt, kann für einen Aktionspunkt den nächsten Gottesdienst ansetzen und dabei jemanden aussuchen, gegen den gepredigt wird. Die Leute der Stadt spenden je nach Frömmigkeit, Glauben und Vermögen, und die Kollekte geht an den Besitzer; die Kirchen der Konkurrenten predigen von selbst. Wie im Original gewinnt der, gegen den gepredigt wurde, bei den Spendern s"},{"p":"baustellen.html","i":"i238","x":"Das Würfelspiel in der Schänke Neu: Am Spieltisch einer Schänke kann man ab Mittag gegen einen Fremden eine Partie „17“ würfeln — wer näher an 17 kommt, ohne darüber zu gehen, gewinnt. Wie im Original sitzt nicht immer jemand da, der Einsatz wächst mit dem Vermögen, und das Talent „Bei Nacht und Nebel“ hilft beim Würfeln. Anders als im Original kommt das Geld nicht aus dem Nichts: Der Wirt hält di"},{"p":"baustellen.html","i":"i239","x":"Der Stammtisch im Gasthaus Neu: Hat ein Gasthaus einen Stammtisch, kann man sich daran setzen — vier Plätze, und an höchstens einem Stammtisch der Stadt zugleich. Jeden Abend zahlt die Runde dem Wirt ihre Zeche, ein Bier und eine Mahlzeit, und alle am Tisch gewinnen an Ansehen beieinander. Im Original kann man den Stammtisch nicht von selbst wieder verlassen — der Knopf dafür ist da, tut aber nich"},{"p":"baustellen.html","i":"i240","x":"Die Dunkle Ecke im Wirtshaus Neu: Der Wirt kann einmal im Jahr einen Spion losschicken. Der geht durch die Stadt, horcht in fünf bis acht Häusern herum und bringt bis zu drei Missetaten mit, die seit dem Auftrag geschehen sind. Gäste können sie dem Wirt einzeln abkaufen und halten dann einen Beweis gegen den Täter in der Hand; je angesehener der Täter beim Käufer und je schwerer die Tat, desto teu"},{"p":"baustellen.html","i":"i241","x":"Die Möbel im Raum Neu: Ein Raum zeigt die Möbel, die sein Besitzer gekauft hat — wie im Original. Bessere Stühle ersetzen die einfachen, und wo der Spieltisch fehlt, steht ein Fass als Tisch. Was nicht dasteht, kann man auch nicht anklicken: ohne Spieltisch kein Würfelspiel. Ein Möbel gehört zu dem Kaufgegenstand, der genau so heißt — auch im Original, nachgelesen. Wo die Spieldaten sich vertippt "},{"p":"baustellen.html","i":"i242","x":"Die Computergegner an der Dunklen Ecke Neu: Auch die Computergegner nutzen jetzt die Dunkle Ecke, wie im Original. Ein Wirt mit hohem Rang schickt seinen eigenen Spion, und andere kaufen nachts in fremden Schänken Informationen, höchstens einmal je Runde und nur, wenn es ihr Geldbeutel leicht hergibt. Wie im Original kauft ein Gegner dort nur um neun Uhr abends, und diese Stunde gehört nur jedem d"},{"p":"baustellen.html","i":"i243","x":"Die Computergegner am Stammtisch Neu: Auch Computergegner setzen sich jetzt an fremde Stammtische und verlassen sie wieder, höchstens einmal am Tag eine solche Entscheidung — so steht es im Programm des Originals. B110"},{"p":"baustellen.html","i":"i244","x":"Das Gebäudemenü Neu: Wer draußen sein Haus anklickt, findet an der Säule den Knopf „Optionen“ — dahinter das Pergament des Originals mit Zustand und Wert des Hauses, „Renovieren lassen“ und „Gebäude um eine Stufe aufwerten“. An fremden Häusern heißt der Knopf „Infos“; darunter öffnet „Transport“ das Lager oder, beim Nachbarn, „Waren einkaufen“. Was das Menü im Original sonst noch anbietet — verkau"},{"p":"baustellen.html","i":"i245","x":"Ein Haus abreißen Neu: Im Gebäudemenü kann man sein Haus abreißen lassen, wie im Original kostenlos und nach fünf Spielminuten; die anderen Spieler lesen „Wie schade… wurde dem Erdboden gleichgemacht“. Noch bleibt das Haus danach in der Stadt sichtbar stehen. B113"},{"p":"baustellen.html","i":"i246","x":"Der Beutel Neu: Ein Klick auf den Sack unten an der Säule öffnet den Beutel „Gegenstände benutzen“. Ein Klick auf einen Gegenstand zeigt, was er tut, mit „Benutzen“ und „Wegwerfen“ — wie im Original; wer ein Ziel braucht, wählt einen Mitspieler. Was auf ein Gebäude zielt, geht noch nicht. B114"},{"p":"baustellen.html","i":"i247","x":"Das Vorrechtsfenster Neu: Ein Klick auf den eigenen Namen oben im Banner öffnet „Eure Privilegien“ — alles, was Titel und Amt erlauben, wie im Original nach denselben 58 Regeln. Was man nur besitzt (Wohnsitz, Leibwächter, Immunität …), erklärt ein Klick in einem eigenen Blatt. Seit dem 15. Oktober öffnen fast alle Handlungen darin ihr Fenster wie im Original — von Erpressung, Werbung und Anklage b"},{"p":"baustellen.html","i":"i248","x":"Medicus, Scheidung, Amt niederlegen Neu: Im Vorrechtsfenster öffnen „Medicus aufsuchen“, „Euch scheiden lassen“ und „Amt niederlegen“ die Fragen des Originals, mit Preis und Aktionspunkten; fehlt etwas, sagt es das Spiel. Der Medicus selbst arbeitet noch nach den Regeln des Neubaus: Er heilt sicher und nimmt einen festen Preis, im Original sind es zwei Prozent des Vermögens und eine Münze von fünf"},{"p":"baustellen.html","i":"i249","x":"Absetzen und Anweisen Neu: Wer ein Amt hat, kann im Vorrechtsfenster die Absetzung eines Ratskollegen beantragen; Reichsmarschall und Graue Eminenz können einen Amtsträger anweisen. Gewählt wird die Person im Bild der Kammer, wie im Original. B117"},{"p":"baustellen.html","i":"i250","x":"Gesetze ändern Neu: Wer ein Amt mit Gesetzen führt, ändert sie im Vorrechtsfenster wie im Original — Prozente mit dem Zähler, Stufen und Glauben durch Klicken auf das Wort, Verbote mit einem Knopf. B118"},{"p":"baustellen.html","i":"i251","x":"Das Beweisbuch Neu: „Anklage erheben“ im Vorrechtsfenster öffnet das Beweisbuch des Originals — wer Beweise gegen wen hat, mit Bild; ein Klick zeigt die einzelnen Taten mit Paragraphenzeichen nach ihrer Schwere und den Knopf „Anklagen“, wie im Original kostenlos. B119"},{"p":"baustellen.html","i":"i252","x":"Wen soll es treffen? Neu: Wer jemandem Furcht einflößen oder ihn beleidigen will, wählt ihn wie im Original aus einer Übersicht der neun Kammern der Stadt — Dynastien, Stadträte, Kirche, Ehrenämter und so weiter — und klickt dann auf das Bild der Person. Danach fragt das Spiel wie im Original nach, die Beleidigung mit einem zufällig gewählten Schimpfwort. Ein paar Kleinigkeiten fehlen noch, etwa d"},{"p":"baustellen.html","i":"i253","x":"Die Stadtkarte Neu: Wo eine Handlung ein Gebäude als Ziel braucht, öffnet das Spiel wie im Original die gemalte Karte der Stadt, mit jedem Haus als kleinem Bild und dem Wappen seines Besitzers; was man wählen darf, wird hell, wenn die Maus darauf steht, und nennt seinen Namen. Als Erstes nutzt sie das Amtsrecht „Arbeiter ausweisen“ des Geheimrats. Am selben Tag kamen der Knopf „Ziel“ für Karren, d"},{"p":"baustellen.html","i":"i254","x":"Einen Betrieb gründen Im Nachbau gründet man einen Betrieb bisher einfach nach seiner Ware, ohne Bauplatz. Im Original wählt man im Baumenü eine Gebäudeart und setzt sie auf einen Bauplatz der Stadtkarte. Entschieden ist: wie im Original. Wie man das Baumenü dort öffnet, ist noch nicht nachgelesen — das ist auch ein Auftrag für die LAN. B122"},{"p":"baustellen.html","i":"i255","x":"Die Bürger der Stadt Begonnen: Die Stadt ist jetzt wie im Original mit ihren Bürgern angelegt. Sie führen Ämter, altern und sterben, Kaiser und Papst gibt es auch, und die Heiratskandidaten kommen aus der Stadt. Offen ist, wie die einfachen Bürger mehr werden, und einiges, was erst geht, wenn Bürger selbst Gebäude führen. C10"},{"p":"baustellen.html","i":"i256","x":"Die Anfangstalente einer Figur Im Original wählt man bei der Charaktererstellung „Automatisch“ — dann gibt der Beruf feste Werte, ohne Würfeln — oder „Stammbaum bestimmen“: Jedes Elternteil bringt 63 Punkte mit, dazu kommen 126 zum freien Verteilen. Entschieden: wie im Original. Gebaut wird es zusammen mit der Wahl von Beruf, Wappen und Gesicht zu Beginn. C43"},{"p":"baustellen.html","i":"i257","x":"Die Leiche für die Séance Im Original sucht man eine Leiche aus den Gräbern aus, mit Bild und Talenten. Bei uns wird sie mitbezahlt, weil Tote noch keine Figuren sind. C139"},{"p":"baustellen.html","i":"i258","x":"Die Computergegner als Familien Gebaut wie im Original: Die Computergegner haben jetzt ein Oberhaupt als Figur, sterben an Überschuldung, vererben per Los, werben, heiraten und bekommen Kinder; ohne Erben erlischt das Haus. Ob ein Computergegner um eine Frau wirbt, entscheidet jetzt wie im Original seine eigene Überlegung, was er als Nächstes tut. Was an dieser Überlegung noch vorläufig ist, steht"},{"p":"baustellen.html","i":"i259","x":"Wie Computergegner ihre nächste Handlung wählen Die Computergegner wählen jetzt wie im Original aus einer Liste von 72 möglichen Handlungen die nützlichste. Gebaut sind davon fünf: das Werben, das Lesen von Fachbüchern, die Dunkle Ecke, der Stammtisch und das Sparen von Aktionspunkten — wer nur etwas tun könnte, das Aktionspunkte kostet, hebt sie lieber auf. Dazu kommen sechs Handlungen, bei denen"},{"p":"baustellen.html","i":"i260","x":"Der Beutel des Spielers Sechs Plätze, alles bekannt und im Kern gebaut — es fehlt nur noch das Fenster dazu. F3"},{"p":"baustellen.html","i":"i261","x":"Die Maßnahmen des Zunftmeisters Das Preisgerücht ist jetzt im Spiel angeschlossen, und das Zunfthaus gibt es inzwischen auch — aber nur in der ersten Stufe. Aufwiegeln und Politik brauchen ein Zunfthaus, das man ausbauen kann. Im Bild fehlen die Knöpfe noch. F21"},{"p":"baustellen.html","i":"i262","x":"Was Gegenstände bewirken Alle 38 Wirkungen sind bekannt, 37 davon wirken inzwischen im Spiel — vom Hexerdokument über die Voodoopuppe bis zur Eifersucht. Es fehlt nur der Schleifstein: Er schont die Waffen der Wachen, und das zählt nur im Kampf mit Einheiten. Der kommt erst, wenn entschieden ist, wie dieser Kampf neu geplant wird. F23"},{"p":"baustellen.html","i":"i263","x":"Der Nebel des Grauens Die Seuchenmaschine des Totengräbers ist vollständig gemessen, bis hin zur Wahrscheinlichkeit, dass sie trifft. Der Nebel wirkt nach Entfernung — die Lage der Betriebe vom Partiebeginn kennt der Nachbau inzwischen, die später gegründeter noch nicht. Außerdem braucht er die Stadtbevölkerung als Opfer. F26"},{"p":"baustellen.html","i":"i264","x":"Auf wen man Gegenstände anwenden kann Viele Gegenstände wirkt man im Original auf eine beliebige Figur der Stadt. Bei uns geht das nur auf Spieler, weil die übrigen Figuren noch keine Talente, Aktionspunkte oder Kerkerstrafen haben. Das kommt mit der echten Bevölkerung. F30"},{"p":"baustellen.html","i":"i265","x":"Bewerber für die Ämter Im Original bewerben sich täglich neue reiche Bürger und die Computergegner um Ämter. Die Bürger bewerben sich seit dem 14. Oktober auch im Nachbau; die Computergegner noch nicht. Ämter"},{"p":"baustellen.html","i":"i266","x":"Die Leiche für den Gehilfen wählen Im Original fragt das Spiel, welche Leiche man für einen neuen Gehilfen nehmen will, und zeigt zu jedem Grab Bild und Talente des Toten. Der Nachbau kann die Wahl schon annehmen, aber das Fenster dafür fehlt noch; bis dahin nimmt er die Gräber der Reihe nach. Dunkle Künste"},{"p":"baustellen.html","i":"i267","x":"Gehilfen verbessern Im Original legt man einen Gehilfen auf den Tisch, und sein Talent steigt in bis zu sechs kleinen Schritten über dreieinhalb Stunden; je Friedhof liegt nur einer zur Zeit dort, und auch der Meister verbessert, das ganze Jahr. Der Nachbau hebt das Talent auf einen Schlag, verlangt Geld, kennt den Meister dabei nicht und bietet Turm und Ausbauten ohne den Turm an. Das wird umgeba"},{"p":"baustellen.html","i":"i268","x":"Gräber pflegen lassen Im Original klickt man ein Grab an und schickt einen ausgewählten Gehilfen hin. Der Nachbau fragt nur, wie viele Gehilfen pflegen sollen, und verteilt sie auf die schlechtesten Gräber. Außerdem pflegt ein faulenzender Gehilfe im Original zu einem Viertel, bei uns gar nicht. Dunkle Künste"},{"p":"baustellen.html","i":"i269","x":"Welche Gräber verwildern Im Original verwildern im Lauf des Jahres nur Gräber, die jemand gepachtet hat. Im Nachbau verwildert jedes Grab, und darum schickt die Pflege ihre Gehilfen auch an Gräber ohne Pächter. Dunkle Künste"},{"p":"baustellen.html","i":"i270","x":"Das Zunfthaus ausbauen Im Original baut nur der Gildenmeister das Zunfthaus aus, bezahlt aus der Zunftkasse, in die auch die Miete der Arbeiter fließt. Seit dem 16. Oktober ist auch der Weg des Spielers gelesen: Er wertet das Zunfthaus im Gebäudemenü auf, für drei Zehntel des Grundpreises aus der Zunftkasse. Im Nachbau gibt es das Zunfthaus bisher nur in der ersten Stufe, ohne Zunftkasse. Stadt"},{"p":"baustellen.html","i":"i271","x":"Der Geldverleiher Beschlossen: Der Geldverleiher wird ein ganzer Beruf wie im Original — die Bank als Betrieb ohne Ware, Kredite wie dort, dann die sieben Währungen mit dem Fernhandel an den Kontoren, Geldwechsel und Geldbote, und zuletzt leihen sich auch die Computergegner Geld. Handel"},{"p":"baustellen.html","i":"i272","x":"Computergegner leihen sich Geld Die Computergegner bauen jetzt aus und ziehen in größere Häuser, wie im Original. Fehlt ihnen dafür nur ein kleiner Rest, nehmen sie im Original einen Kredit bei einer fremden Bank. Das fehlt noch, weil es im Nachbau die Bank als Geldgeber noch nicht gibt, nur das Konto des Spielers. KI"},{"p":"baustellen.html","i":"i273","x":"Computergegner wachsen ohne Grenze Im Original gründet ein Gegner höchstens drei Betriebe, und um 1460 hört das Wachsen auf. Entschieden: bewusst anders — die Gegner sollen aus Eigeninteresse endlos wachsen wollen, wie der Spieler. Wonach sie entscheiden, ob sich eine weitere Gründung lohnt, ist eine neue Regel ohne Vorlage. KI"},{"p":"baustellen.html","i":"i274","x":"Den Namen des Kindes wählen Im Original fragt das Spiel bei der Geburt „Wie soll Euer Sohn heißen?\". Bei uns wird der Name ausgewählt. Familie"},{"p":"baustellen.html","i":"i275","x":"Wo das Geld hinfließt Dein Grundsatz: Im Nachbau verschwindet kein Geld, und die Stadt bekommt keines aus dem Nichts — sie wirtschaftet wie jeder andere. Fast alles ist danach gebaut: Steuern, Amtseinkommen, Baugeld, Pleite mit Neustart. Inzwischen ist auch die Versteigerung der Pacht gebaut: Wer am meisten bietet, wird Eigentümer, und das Geld geht zu neun Zehnteln an die Stadt. Offen ist nur noc"},{"p":"baustellen.html","i":"i276","x":"Beim Nachbarn einkaufen Die Warenfächer funktionieren jetzt wie im Original, aber gekauft wird erst mit einem Klick auf das Ziel: den eigenen Karren vor dem Gebäude oder den Beutel. Beides hat der Nachbau dort noch nicht, darum geht der Kauf beim Nachbarn gerade gar nicht. Ein Notknopf wird bewusst nicht gebaut. Handel"},{"p":"baustellen.html","i":"i277","x":"Eine Probe, die manchmal fällt Eine Probe für das Wiederverbinden nach einem Netzabbruch fiel zweimal, wenn alle Proben zugleich liefen, und bestand danach neunmal. Ob die Probe zu ungeduldig ist oder das Wiederverbinden zu langsam, ist noch nicht untersucht. Technik"},{"p":"baustellen.html","i":"i278","x":"Seit dem 13. Oktober stehen Kölns Häuser auf dem Gelände, wie die Engine sie rechnet, der Boden ist bemalt wie im Original, und ein Klick führt in ein Haus und wieder hinaus. Die Stadt dämmert nach der Uhr des Spiels, es regnet und schneit, die Laternen flackern. Jeder Spieler wohnt in einem echten Haus der Stadt, dem freien, das seiner Werkstatt am nächsten steht. Offen ist vor allem, daß die Räu"},{"p":"baustellen.html","i":"i287","x":"Ein Rest in den Spielskripten Viele Abläufe des Originals stehen in kleinen Skripten, etwa was ein Geselle in der Werkstatt Schritt für Schritt tut. Unser Lesewerkzeug zieht diese Abläufe heraus, kennt aber ein paar Befehle noch nicht und überspringt sie — wie viele, zeigt der Balken „Skriptbefehle zugeordnet“ oben. Meist drehen oder verschieben sie Gegenstände im Raum, und welche Zahl welche Achs"},{"p":"einstieg.html","i":"i288","x":"Handwerk und Betrieb Gründen, ausbauen, Personal einstellen. Jeder Angestellte ist eine Person mit Namen und Dienstjahren — nach vier Jahren wird er Geselle. Karren auf Handelsrouten und im Auftrag des Meisters, Kontor, Meisterprüfung."},{"p":"einstieg.html","i":"i289","x":"Markt und Geld Angebot, Nachfrage und wandernde Preise. Kredit und Tilgung nach Bürgertitel, Steuern, Zoll und Zehnt — und wer pleitegeht, wird gepfändet und beginnt als neue Dynastie."},{"p":"einstieg.html","i":"i290","x":"Stadt und Ämter Der Rat wählt und setzt ab, mit gewichteten Stimmen und Wahl reihum. Der Bürgermeister bestimmt Steuer und Prunk; die Gesetze greifen wirklich in die Wirtschaft ein. Jedes Amt hat seine Handlungen — Absetzen, Verhören, Unterschlagen, Wunder wirken."},{"p":"einstieg.html","i":"i291","x":"Familie und Stand Werbung, Trauung als Fest für alle, Kinder, Lehre und Studium, Erbfolge. Der Wohnsitz vom Haus bis zum Palazzo, der Titelaufstieg und die Vorrechte, die daran hängen."},{"p":"einstieg.html","i":"i292","x":"Unterwelt und Gericht Diebstahl, Sabotage, Bestechung, Erpressung, Entführung, Duell. Anklage, Prozeß, Folter und Kerker — samt der Bestechung des Kerkermeisters. Das Pamphlet am Schwarzen Brett."},{"p":"einstieg.html","i":"i293","x":"Dunkle Künste Friedhof mit Gräbern und Gehilfen, Alchemie, Séance in der Krypta, Pakt mit dem Tod, neun Krankheiten und der Medicus — und der Kanonenturm auf Burg und Schloß."},{"p":"einstieg.html","i":"i294","x":"Zu mehreren spielen Ein Server führt die Welt, mehrere Spieler hängen sich dran. Wer rausfliegt, kommt mit seiner Wertmarke zurück an denselben Platz. Die ganze Partie läßt sich speichern."},{"p":"einstieg.html","i":"i295","x":"Die Originalwelt Räume, Modelle, Texturen, Figuren und Texte kommen unverändert aus den Spieldateien. Gespielt wird Köln — mit Bürgern, Tag und Nacht, Wetter und Katastrophen, und die Leute laufen dieselben Arbeitswege wie im Original."},{"p":"einstieg.html","i":"b-aktionspunkte","x":"Aktionspunkte — Die Punkte, die man je Runde für Handlungen ausgibt — Bestechen, Werben, Anklagen und vieles mehr."},{"p":"einstieg.html","i":"b-bauposten","x":"Bauposten — Etwas, das im Original gemessen ist und im Nachbau noch gebaut werden muss."},{"p":"einstieg.html","i":"b-beutel","x":"Beutel — Das Inventar der Spielfigur: sechs Sorten Gegenstände zu je drei Stück."},{"p":"einstieg.html","i":"b-bevölkerung","x":"Bevölkerung — Die Bürger der Stadt als echte Figuren mit Namen, Alter und Glauben. Im Original gibt es sie; der Nachbau zählt sie bisher nur."},{"p":"einstieg.html","i":"b-bürgerrecht","x":"Bürgerrecht — Der erste Titel über dem Stand eines einfachen Einwohners. Im Original kauft man ihn im Rathaus."},{"p":"einstieg.html","i":"b-computergegner","x":"Computergegner — Die Dynastien und Figuren, die das Spiel selbst steuert."},{"p":"einstieg.html","i":"b-gelände","x":"Gelände — Die Landschaft draußen: Höhen, Wege und wie die Häuser darauf stehen."},{"p":"einstieg.html","i":"b-gemessen","x":"gemessen — Aus den Spieldateien, aus dem Programm des Originals oder am laufenden Spiel abgelesen — nicht angenommen."},{"p":"einstieg.html","i":"b-geraten","x":"geraten — Eine Zahl, die jemand angenommen hat, weil sie noch nicht gemessen war. Sie ist gekennzeichnet, bis sie gemessen ist."},{"p":"einstieg.html","i":"b-gildensteuer","x":"Gildensteuer — Die Steuer der Zünfte. Wer sie nicht zahlt, zahlt Umsatzsteuer."},{"p":"einstieg.html","i":"b-handelsroute","x":"Handelsroute — Eine feste Fahrt, die ein Karren immer wieder abfährt, mit Halt zum Laden und Abladen."},{"p":"einstieg.html","i":"b-handgriff","x":"Handgriff — Eine Handlung im Spiel, etwa „Betrieb gründen“ oder „Anklage erheben“. Im Nachbau sind alle da; manchen fehlt nur noch der Knopf im Bild."},{"p":"einstieg.html","i":"b-kleinreste","x":"Kleinreste — Einzelne offene Punkte, die nicht in der großen Liste der geratenen Zahlen stehen."},{"p":"einstieg.html","i":"b-kontor","x":"Kontor — Das Lager eines Betriebs für Waren, die gerade nicht gebraucht werden. Im Abschnitt „Im Kontor“ heißt es auch: Arbeit am Schreibtisch, ohne Spiel."},{"p":"einstieg.html","i":"b-meisterauftrag","x":"Meisterauftrag — Der Meister eines Betriebs handelt auf eigene Faust: Er schickt Karren zum Einkaufen und Verkaufen."},{"p":"einstieg.html","i":"b-nachbau","x":"Nachbau — OpenGilde: das Spiel, neu geschrieben, das genauso funktionieren soll wie das Original."},{"p":"einstieg.html","i":"b-original","x":"Original — „Die Gilde 1400“ aus dem Jahr 2002, so wie es auf der CD war."},{"p":"einstieg.html","i":"b-proben","x":"Proben — Kleine Prüfprogramme, die nach jeder Änderung nachrechnen, ob der Nachbau noch tut, was er soll."},{"p":"einstieg.html","i":"b-reichsämter","x":"Reichsämter — Die höchsten Ämter über der Stadt, bis hinauf zum Kurfürsten."},{"p":"einstieg.html","i":"b-spielstand","x":"Spielstand — Eine gespeicherte Partie des Originals. Der Nachbau liest daraus tausende Zahlen auf einmal."},{"p":"einstieg.html","i":"b-séance","x":"Séance — In der Krypta befragt man die Geister — und kann dort auch den Teufelspakt schließen."},{"p":"einstieg.html","i":"b-teufelspakt","x":"Teufelspakt — Geld vom Teufel, das in drei Jahren zurückzuzahlen ist. Sonst trifft die Familie ein großes Unglück."},{"p":"einstieg.html","i":"b-zunfthaus","x":"Zunfthaus — Das Haus einer Zunft. Es entsteht, sobald ein Gewerk drei Betriebe in der Stadt hat."},{"p":"wissen-fuhrwesen.html","i":"i296","x":"I Drei Karren Handkarren Handelskarren Pferdekarren Preis 400 800 1.500 Ladeplätze 1 2 3 Stück je Platz 15 20 25 zusammen 15 40 75 Jeder Platz faßt eine Warensorte. Die volle Ladung erreicht also nur, wer ebenso viele Sorten auflädt, wie der Karren Plätze hat. Ein Gebäude hält höchstens drei Karren — „bereits 3 Fuhrleute angestellt\". Gekauft wird nur im eigenen Betrieb, und der Karren steht sofort"},{"p":"wissen-fuhrwesen.html","i":"i297","x":"II Wie schnell er fährt Auf demselben Boden, ohne Deichsel, der heile Handkarren gleich 100: Zustand Hand Handel Pferd heil (100) 100 121 120 halb (50) 82 104 90 hinüber (0) 64 86 60 Der Handelskarren ist bei jedem Zustand der schnellste. Der Pferdekarren hält nur heil mit ihm Schritt; er leidet unter dem Verschleiß am stärksten und fällt unter Zustand 20 sogar hinter den Handkarren. Wer schnell s"},{"p":"wissen-fuhrwesen.html","i":"i298","x":"III Was ihn schneller macht, was ihn bremst Schneller machen ihn allein die Deichseln der Lagergebäude — und nur für Karren, die in diesem Lager zu Hause sind. Ein Werkstattkarren bekommt nie einen Aufschlag. Heimat schneller um Lagerschuppen (einspännige Deichsel) 30 % Lagerhaus (dazu zweispännig) 55 % Lagerhalle (dazu vierspännig) 80 % Der Aufschlag gilt mal dem Zustand des Lagers: Eine Lagerhal"},{"p":"wissen-fuhrwesen.html","i":"i299","x":"IV Der Zustand Der grüne Balken unter dem Karrenbild läuft von 0 bis 100. Er sinkt nicht gleichmäßig: Bei jeder Ankunft verliert der Karren mit knapp einem Viertel Wahrscheinlichkeit (24 %) zwei Punkte, sonst nichts. Der Balken steht also still und springt dann. Ohne Pannen gerechnet braucht ein neuer Karren rund 150 Fahrten, bis er in den gefährlichen Bereich kommt. Der Zustand wirkt dreifach: au"},{"p":"wissen-fuhrwesen.html","i":"i300","x":"V Der Zusammenbruch „Wegen seines schlechten Zustandes ist einer Eurer Karren zusammengebrochen! Alle Waren sind verloren\" — und der Karren mit ihnen. Er verschwindet aus seinem Gebäude. Zustand Gefahr 29 und mehr keine 28 3 % 20 30 % 10 63 % 0 97 % Über 28 bricht kein Karren zusammen."},{"p":"wissen-fuhrwesen.html","i":"i301","x":"VI Gewürfelt wird nur auf langen Fahrten Unterwegs sieht das Spiel in festen Abständen nach, ob der Karren angekommen ist — beim schnellsten Spieltempo alle 7½ Minuten, das erste Mal beim Losfahren. Zusammenbruch und Panne werden genau einmal gewürfelt, beim fünften Nachsehen, also eine halbe Stunde nach der Abfahrt. Kurze Wege sind sicher. Kommt der Karren binnen gut zwanzig Minuten an, wird gar "},{"p":"wissen-fuhrwesen.html","i":"i302","x":"VII Die Panne Der zweite Wurf fällt im selben Augenblick und trifft auch heile Karren. Schützen kann Euch der Unfallschutz des Heimatgebäudes — dieselben Ausbauten, die Eure Arbeiter vor Unfällen bewahren, die Schürze etwa. In fast allen Gebäuden läßt er sich auf das Höchstmaß ausbauen. Zustand ohne Schutz voller Schutz 100 4 % 0 80 23 % 0 58 44 % 0 50 51 % 13 % 20 80 % 65 % 0 99 % 99 % Schnee und"},{"p":"wissen-fuhrwesen.html","i":"i303","x":"VIII Ausbessern Der Knopf Reparieren erscheint nur im eigenen Betrieb und ist nur hell, wenn ein markierter Karren unter 100 steht. Ausgebessert wird immer ganz und vorher in einem Betrag bezahlt. je Punkt von 0 auf 100 Handkarren 3,2 320 Handelskarren 6,4 640 Pferdekarren 12 1.200 Das sind 0,8 % des Kaufpreises je Punkt — ein Wrack instand zu setzen kostet 80 % eines neuen. Dafür dauert es: beim "},{"p":"wissen-fuhrwesen.html","i":"i304","x":"IX Die Handelsroute Der Routenschalter am Karren öffnet das Routenfenster mit einer Stadtkarte. Der erste Halt ist immer der Heimatbetrieb, und die Route ist sofort aktiv. Neue Halte kommen stets hinten dazu, jedes Gebäude nur einmal, höchstens acht. Jeder Halt bekommt auf der Karte eine Nummer, und die Nummern rücken nach, wenn einer wegfällt. Umsortieren kann man nicht. Anfahren läßt sich fast j"},{"p":"wissen-fuhrwesen.html","i":"i305","x":"X Wie die Route gefahren wird Eine Aufsicht geht beim schnellsten Tempo alle 17½ Minuten alle Karren durch. Ein Karren kommt nur dran, wenn er steht. Am Halt wird zuerst abgeladen, dann, falls geschlossen ist, in Viertelstunden auf die Öffnung gewartet, dann aufgeladen. Je Halt steht der Karren nach der Rechnung eine gute Viertel- bis halbe Stunde. Vor jedem Umlauf wartet er am Heimatbetrieb, und "},{"p":"wissen-fuhrwesen.html","i":"i306","x":"XI Die Route bessert selbst aus Steht ein Routenkarren, würfelt die Aufsicht bei jedem Durchgang, ob sie ihn ausbessert — an Ort und Stelle, ohne Fahrt, ohne Meldung: Zustand je Durchgang 71 und mehr nie 70 3 % 60 34 % 50 66 % unter 40 immer Der Preis ist derselbe wie im Fenster, die Arbeit dauert etwas länger, gut sechs Minuten je Punkt. Reicht Euer Geld nicht, wird trotzdem ausgebessert — die Za"},{"p":"wissen-fuhrwesen.html","i":"i307","x":"XII Fernhandel Die drei Kontore stehen an den Kölner Stadttoren: Augsburg im Süden, Dresden im Osten, Hannover im Norden. Die Reise in die fremde Stadt endet dort — eine eigene Reisezeit gibt es nicht. Auf der Karte erscheinen die Kontore nur, wenn Ihr ein Lagergebäude besitzt. Sie gehören der Stadt, und gehandelt wird zu den Preisen und in der Währung der fremden Stadt. Von Hand hinschicken läßt "},{"p":"wissen-fuhrwesen.html","i":"i308","x":"XIII Wenn ein Meister mitredet Stellt Ihr einen Meister ein, dessen Brief auf „Darf sich einmischen\" steht, übernimmt er die Karren seines Betriebs. Ihr seht sie dann nur noch: keine Route, keine Eskorte, kein Be- und Entladen — „Dieser Karren wird von einem Meister benutzt!\". Eine eingerichtete Route bleibt liegen, solange er da ist. Der Meister wird ab halb sieben tätig, verkauft am Markt zu 90 "},{"p":"wissen-fuhrwesen.html","i":"i309","x":"XIV Die Eskorte Der Knopf unten links am Karren schaltet reihum: ohne, leicht, schwer. Die „sehr schwere Eskorte\" steht zwar in den Texten, kein Weg im Spiel führt zu ihr. Bezahlt wird beim Losschicken, ein Anteil am Wert der Ladung. Dabei zählt jede Ladung mindestens als 1.000 und höchstens als 8.000 Gulden: Eskorte Anteil kostet leicht 5 % 50 – 400 schwer 10 % 100 – 800 Ein leerer Karren fährt u"},{"p":"wissen-fuhrwesen.html","i":"i310","x":"XV Wen die Räuber wählen Räuber legen sich auf die Lauer, jeweils zwei Runden lang, und schauen etwa alle Viertelstunde nach Beute. Sie sehen dabei jeden fahrenden, beladenen Karren der ganzen Karte — die eigenen ausgenommen. Genommen werden Karren, die nahe am Lauerplatz vorbeifahren, oder solche, deren Ladung in ihr Wertband paßt. Dieses Band hängt am Talent Bei Nacht und Nebel: Die geübtesten B"},{"p":"wissen-fuhrwesen.html","i":"i311","x":"XVI Im Überfall „Einer Eurer Transporte wird von hinterhältigen Räubern überfallen!\" Dann habt Ihr vier Knöpfe: Knopf Flucht gelingt verloren Wenige Waren zurücklassen 1 % 10 % Einige Waren 46 % 50 % Viele Waren 90 % 90 % Euch mutig zum Kampfe stellen! — — „Viele\" nennt im Text 80 % des Werts, nimmt aber 90 % jedes Stapels, und von jedem Stapel mindestens ein Stück. Mißlingt die Flucht — „Die Ladu"},{"p":"wissen-fuhrwesen.html","i":"i312","x":"XVII Beute und Folgen Nach der Flucht geht der zurückgelassene Anteil in das Lager der Räuber. Gewinnt der Räuber den Kampf, nimmt er alle ganzen Stapel aller Karren — jeden, der ganz in sein Lager paßt. Auch wenn Ihr siegt, gehen die Stapel verloren, die ein Räuber im Kampf aufgehoben und nicht wieder fallen gelassen hat. Der Karren selbst bleibt Euch; die Fuhrleute kämpfen nicht und sterben nich"},{"p":"wissen-fuhrwesen.html","i":"i313","x":"XVIII Der Geldsack im Transportfenster Oben im Transportfenster liegt ein Geldsack. Er ist kein Schmuck, sondern ein Schalter: Ein Klick blendet statt der Karrenliste Euren Beutel ein, sechs Fächer für Gegenstände. Damit räumt Ihr Gegenstände um, ohne Geld: Ihr stellt ein im … und klickt auf … dann wandert es Beutel das eigene Gebäude aus dem Beutel ins Lager Lager den Beutel aus dem Lager in den "},{"p":"wissen-fuhrwesen.html","i":"i314","x":"XIX Kleinigkeiten Ein Karren kehrt nie von selbst heim. Er bleibt im letzten Ziel stehen, am Markt sichtbar auf der Straße, in einem Gebäude unsichtbar. „Schnell dorthin\" im Personalbuch holt den Karren nicht; es springt nur mit der Ansicht hin. Fuhrleute haben keinen Namen und bekommen keinen Lohn. Die Plane trägt die Farbe Eurer Dynastie. Der Warenkorb im Transportfenster wirft Ware weg, er lage"},{"p":"wissen-fuhrwesen.html","i":"i315","x":"XX Sieben Ratschläge Setzt Karren auf eine Route. Sie bessert selbst aus und läßt keinen unter 40 losfahren — so bricht keiner zusammen. Und am Markt verkauft sie besser als Ihr von Hand. Baut Unfallschutz in die Heimat. Er schützt die Arbeiter und die Karren zugleich. Nehmt für Tempo den Handelskarren, für Menge den Pferdekarren — und haltet diesen heil. Lange Fahrten sind die gefährlichen. Ein W"},{"p":"wissen-meister.html","i":"i316","x":"I Wer einen Betrieb führt Solange kein Meister eingestellt ist, heißt es: „Ihr leitet diesen Betrieb selbst!\" Dann teilt niemand Eure Leute ein. Wer keiner Ware zugewiesen ist, steht herum — seine Karte zeigt weder Werkzeug noch Ware — und bekommt seinen Lohn trotzdem. Ein eingestellter Meister übernimmt die Führung, aber nur, wenn sein Meisterbrief auf „Darf sich in den Betrieb einmischen\" steht."},{"p":"wissen-meister.html","i":"i317","x":"II Wen Ihr bekommt Er kommt immer mit dem höchsten Grad, den sein Handwerk kennt — in Gießerei, Schmiede und Goldschmiede ein Meisterschmied, in der Tischlerei ein Kunsttischler, in der Schänke ein Patron. Wählen läßt sich der Grad nicht. Zuerst sucht das Spiel in der Stadt jemanden, der genau diesen Grad trägt und frei ist. Erst wenn keiner paßt, kommt ein Neuer, achtzehn Jahre alt. Er tritt so g"},{"p":"wissen-meister.html","i":"i318","x":"III Was er kostet Der Preis hängt am Schwierigkeitsgrad. In den meisten Betrieben: Schwierigkeitsgrad Anwerben Sehr leicht 462 Leicht 693 Normal 924 Schwer 1.155 Sehr schwer 1.386 Beim Waldstück und beim Steinbruch ist er dreimal so teuer. Das Geld bekommt der Meister selbst, als Handgeld — es verschwindet nicht."},{"p":"wissen-meister.html","i":"i319","x":"IV Was er verdient — eine Merkwürdigkeit Im Personalbuch steht zu jedem Meister ein Lohn. Am Lohntag zahlt das Spiel ihn aber nicht so aus. Es sortiert die Belegschaft nach ihrem Handwerk in Gesellen, Lehrlinge, den Meister und alle übrigen, und den Meisterplatz zahlt es gar nicht: Meister was er am Lohntag bekommt der, mit dem Ihr die Partie beginnt den Lohn eines Lehrlings — er trägt dessen Hand"},{"p":"wissen-meister.html","i":"i320","x":"V Er arbeitet nicht mit Ein Meister, den Ihr anwerbt, bringt kein eigenes Handwerk mit. Er teilt ein, aber er steht an keiner Ware und erscheint nicht unter den Karten Eurer Leute. Die Behandlung aus dem Personalbuch trifft ihn nicht. Sie wirkt alle sechzig Arbeitsminuten auf jeden, der an einer laufenden Ware steht — und zwar für jede Ware eigens gezählt. Eine Prämie dagegen teilt sich auch auf i"},{"p":"wissen-meister.html","i":"i321","x":"VI Der Meisterbrief Der Brief gehört dem Gebäude, nicht dem Mann. Ein neuer Meister übernimmt, was dort eingestellt ist; wer die Schalter umlegt, stellt Gebäude und Meister zugleich um. Schalter ohne ihn Einmischen tut der Meister gar nichts Personal stellt er niemanden ein Karren kauft er keine Karren — außer im Lager Erweiterungen baut er nicht aus und renoviert nicht Beim Bau eines Betriebs ist"},{"p":"wissen-meister.html","i":"i322","x":"VII Sein Tag wann was er tut ständig, ab halb sieben zieht alle Leute im Gebäude ab und verteilt sie neu; kauft Lagerplätze etwa jede Stunde bessert Karren aus 7, 12 und 18 Uhr stellt Leute ein, baut aus, renoviert 8 und 13 Uhr wählt die Ware neu jede ungerade Stunde holt Karren heim, kauft Karren, prüft den Verkauf ab 20 Uhr gibt einen Handel auf, der nichts findet Eingestellt wird bis zur Höchst"},{"p":"wissen-meister.html","i":"i323","x":"VIII Welche Ware er herstellt Er bleibt bei seiner Ware, solange sie herstellbar ist. Neu gewählt wird nur um 8 und um 13 Uhr — oder wenn die laufende Ware nicht mehr geht. Dann würfelt er nach Euren Warenanteilen: Eine Ware mit 40 Anteilen kommt doppelt so oft dran wie eine mit 20. Angefangen wird eine Ware nur, wenn ihre Zutaten für einen vollen Gang im Lager liegen; fehlt etwas, kauft er erst n"},{"p":"wissen-meister.html","i":"i324","x":"IX Wie er einteilt Bei jedem Uhrschritt zieht er alle Leute ab, die im Gebäude stehen, und stellt sie wieder hin — beim schnellsten Spieltempo alle zweieinhalb Spielminuten. Meist an dieselbe Ware. An einer Ware stehen höchstens acht Leute. Die Zutaten werden erst mit dem fertigen Stück verbraucht. Bricht eine Herstellung ab, geht nur die angefangene Arbeit verloren; die Zutaten liegen noch im Lag"},{"p":"wissen-meister.html","i":"i325","x":"X Wie er einkauft Er kauft eine Zutat nach, sobald weniger als vier Gänge davon im Lager liegen oder unterwegs sind. Aufgefüllt wird dann auf einen halben freien Lagerplatz, begrenzt vom Budget. Er kauft auch aus den Zutatenlagern der Konkurrenz — dort zum Stadtpreis, am Markt zu 110 %. Liegt die Zutat in einer fremden Werkstatt, geht er nach der Rechnung des Programms dorthin und nicht zum Markt;"},{"p":"wissen-meister.html","i":"i326","x":"XI Wann er verkauft Geprüft wird jede ungerade Stunde, Ware für Ware — und zwar nur mit Karren, die in diesem Augenblick frei daheim stehen. Verkauft wird nur am Markt, zu 90 % des Stadtpreises; an eine andere Werkstatt verkauft er nie. Anlaß was er verkauft der Stadtpreis erreicht Euer Verkaufsniveau den ganzen Bestand Budget unter 100 oder Euer Bargeld unter 250 Gulden so viel, bis er auf rund 1"},{"p":"wissen-meister.html","i":"i327","x":"XII Er nimmt Euch die Karren Ein angestellter Meister, der sich einmischen darf, übernimmt alle Karren seines Betriebs. Ihr seht sie dann nur noch: „Dieser Karren wird von einem Meister benutzt!\" keine Handelsroute — eine eingerichtete bleibt liegen, solange er da ist, keine Eskorte, kein Beladen, kein Abladen, keine Meldungen: weder Ankunft noch Panne. Legt Ihr „Einmischen\" aus, habt Ihr die Karr"},{"p":"wissen-meister.html","i":"i328","x":"XIII Was er mit den Karren tut Er schickt jeden Karren mit einem eigenen Auftrag los: bis zu drei Waren zum Verkauf und drei zum Einkauf. Ein Karren fährt erst wieder, wenn sein Auftrag erledigt ist. Zum Markt schickt er ihn zum nächstgelegenen, nach Luftlinie. Findet er nichts, wartet er eine halbe Stunde, höchstens viermal. Verlorene Karren holt er jede ungerade Stunde heim. Wie viele solcher Au"},{"p":"wissen-meister.html","i":"i329","x":"XIV Wann er Karren kauft Nur mit dem Schalter Karren, und in dieser Reihenfolge: Kein Karren im Betrieb: sofort ein Handkarren — ohne aufs Budget zu sehen, und auch dann, wenn Ihr ihn nicht bezahlen könnt. Schon einer da: selten ein Handelskarren — im günstigsten Fall mit 2,4 % je Runde, im Mittel also nach gut vierzig Runden, und nur, wenn das Budget mehr als das Doppelte des Preises (800 Gulden)"},{"p":"wissen-meister.html","i":"i330","x":"XV Eine Anschaffung je Runde Ausbau, Renovierung, Lagerplätze, Lagererweiterung und ein weiterer Karren teilen sich eine Anschaffung je Runde; ist sie verbraucht, stellt er auch niemanden mehr ein, solange schon Leute da sind. Die Lagerkäufe stehen vorn und kommen meist schon vor sieben Uhr zum Zug. Solange es Lager zu kaufen gibt, kommt kein zweiter Karren. Ausbauen und renovieren darf er in Eure"},{"p":"wissen-meister.html","i":"i331","x":"XVI Was er nicht tut Er bewaffnet praktisch niemanden. Der Meister einer Diebesgilde oder Raubritterfeste kauft Waffen ins Lager, teilt sie aber nicht aus: Er sieht nur beim ersten Mann nach, ob der ein Richtschwert oder eine Richtaxt trägt, und gibt auf, wenn nicht. Die Spielstände passen dazu, beweisen es aber nicht. Er beliefert kein Kontor. Der Lagermeister eines Computergegners plant Fernhand"},{"p":"wissen-meister.html","i":"i332","x":"XVII Wie man im Handwerk aufsteigt Jedes Handwerk hat sechs Grade, vom Lehrling bis zum Meister. Wie man von einem zum nächsten kommt, ist für Euch und für alle anderen verschieden. Ihr selbst studiert. Im Arbeitszimmer Eures Hauses steht ein Balken, der zeigt, wie weit Ihr seid. Ist er voll, dürft Ihr für vier Aktionspunkte das Studium für den nächsten Grad beginnen. Wie lange der Balken braucht,"},{"p":"wissen-meister.html","i":"i333","x":"XVIII Kleinigkeiten In der Netzpartie führt jeder Rechner die Meister seines eigenen Spielers; Warenanteile und Verkaufsniveau gehen gar nicht über das Netz. Stirbt der Meister oder geht er, bleibt der Brief am Gebäude — der nächste bekommt dieselben Schalter. Waldstück, Steinbruch und Mine der Stadt bekommen ihren Meister von selbst."},{"p":"wissen-meister.html","i":"i334","x":"XIX Sieben Ratschläge Stellt einen Meister ein, sobald Ihr mehr Leute habt, als Ihr selbst einteilen mögt. Ohne ihn stehen sie untätig und kosten trotzdem Lohn. Setzt das Verkaufsniveau bewußt. Bei 100 % verkauft er, sobald der Grundpreis erreicht ist — wer mehr will, stellt es höher. Setzt unerwünschte Waren auf null und haltet ihre Zutaten knapp — sonst kann er sie über den Rückfall doch herstel"},{"p":"wissen-das-eigene-haus.html","i":"i335","x":"I Die zwei Knöpfe an der Säule Wer draußen in der Stadt ein Haus anklickt, sieht an der Säule rechts dessen Tafel mit zwei Knöpfen. Oben steht „Optionen“, wenn es Euer Haus ist, und „Infos“, wenn es einem anderen gehört. Darunter steht „Transport“: Am eigenen Haus öffnet er das Lager zum Verladen, beim Nachbarn das Fenster „Waren einkaufen“. Nicht jedes Haus hat diese Knöpfe. Marktplatz, Kontor un"},{"p":"wissen-das-eigene-haus.html","i":"i336","x":"II Zustand und Wert hängen zusammen Das Gebäudemenü beginnt mit einem Satz wie „Das Gebäude ist in tadellosem Zustand und eine erkleckliche Summe wert“. Die beiden Wörter wirken wie zwei getrennte Auskünfte — sie sind es nicht. Das Spiel rechnet aus dem Zustand eine einzige Stufe von 0 bis 9 und nimmt für beide Wörter dieselbe: vom „prächtigsten“ Zustand und einem „fürstlichen“ Wert bis zu „grauen"},{"p":"wissen-das-eigene-haus.html","i":"i337","x":"III Woraus der Wert besteht Der Wert eines Hauses ist kein Kaufpreis, den sich das Spiel merkt. Es rechnet ihn jedes Mal neu zusammen: einen festen Sockel aus den Baukosten des Hauses, dazu jeden Raum und jeden Anbau, der wirklich steht, und alles, was darin steht, jedes Stück mit seinem gewöhnlichen Preis. Zum Schluß nimmt es davon den Anteil, den der Zustand hergibt. Ein heruntergekommenes Haus "},{"p":"wissen-das-eigene-haus.html","i":"i338","x":"IV Renovieren Steht ein Haus auf vollem Zustand, sagt das Spiel nur „bereits in tadellosem Zustand“. Sonst fragt es, was Ihr tun wollt, und bietet drei Arbeiten mit ihrem Preis an: Flickschusterei, Ausbessern, Sanieren — oder „Das Gebäude hält noch ein paar Jahre!“."},{"p":"wissen-das-eigene-haus.html","i":"i339","x":"V Aufwerten Ein Betrieb läßt sich zur nächsten Stufe ausbauen, die Gießerei etwa zur Schmiede. Das Spiel prüft vorher drei Dinge, und jede Absage hat ihren eigenen Satz: 1. Ist schon die höchste Ausbaustufe erreicht? 2. Habt Ihr den nötigen Meistergrad — bei den Handwerksbetrieben — oder sonst den nötigen Titel? 3. Paßt das größere Haus auf den Bauplatz? Erst dann nennt es den Preis. Reicht das Ge"},{"p":"wissen-das-eigene-haus.html","i":"i340","x":"VI Abreißen Abreißen kostet nichts — und bringt auch nichts. Kein Erlös, keine Rückzahlung. So läuft es ab: Alle, die in dem Haus arbeiten, hören sofort auf und werden hinausgeschickt. Fünf Spielminuten später fällt das Haus. Jeder andere Spieler bekommt die Nachricht „Wie schade…“, daß das Gebäude dem Erdboden gleichgemacht wurde. Nur der Besitzer selbst nicht. Ein Rathaus läßt sich nie abreißen "},{"p":"wissen-das-eigene-haus.html","i":"i341","x":"VII Verkaufen ist eine Ausschreibung Wer ein Haus verkaufen will, bekommt nicht einfach Geld dafür. Das Spiel kennt keinen Restwert und keine Auszahlung. Ihr schreibt das Haus im Gebäudemenü aus, zu einem Preis, den Ihr selbst wählt — der Regler reicht von der Hälfte bis zum Anderthalbfachen des Werts, als Vorschlag steht der Wert selbst darin. Jeder andere Spieler erfährt davon, und im Rathaus er"},{"p":"wissen-das-eigene-haus.html","i":"i342","x":"VIII Ein fremdes Haus kaufen Am fremden Haus heißt es umgekehrt: Ist es ausgeschrieben, steht im Menü „Kaufen“, sonst „Kaufangebot“. An den Zunfthäusern etwa fehlen beide. Kaufen geht nur zum verlangten Preis, und nur, wenn Ihr den nötigen Titel oder Meistergrad habt — sonst sagt Euch das Spiel genau das. Ein Waldstück, einen Steinbruch oder eine Mine kauft auf diesem Weg nie jemand. Dann zählt da"},{"p":"wissen-das-eigene-haus.html","i":"i343","x":"IX Waldstück, Steinbruch und Mine Eine Pachtstätte trägt im Gebäudemenü keinen gewöhnlichen Verkauf, sondern einen Punkt „Verkaufen“ an die Stadt — zu einem festen Preis, ohne Ausschreibung und ohne Warten. Wie der Preis entsteht, erzählt der Artikel über Pacht und Versteigerung."},{"p":"wissen-das-eigene-haus.html","i":"i344","x":"X Was sonst im Menü steht Je nach Haus kommen weitere Zeilen dazu: Anbauen öffnet das Fenster für die Erweiterungen. Räume gibt es nur in Häusern mit mehr als einem Raumplatz — das einfache Haus hat den Punkt gar nicht. Ein Wohnhaus bekommt beim Bau seine Pflichträume: jedes das Arbeitszimmer, Villa und Palazzo dazu den Weinkeller, der Palazzo auch das Musikzimmer. Sie zählen mit, darum ist ein ne"},{"p":"wissen-pacht.html","i":"i345","x":"I Es gibt keine Jahrespacht Das Gesetz heißt „Pachtpreise“, der Beamte heißt Pachtmeister, und jeder Spieler stellt sich darunter eine jährliche Abgabe vor. Die gibt es nicht. Die Stadt setzt ein Waldstück, einen Steinbruch oder eine Mine zur Versteigerung, wer gewinnt, zahlt sein Gebot einmal — und gehört ihm die Stätte danach. Nicht auf Zeit, sondern als Eigentum: Eine Laufzeit, nach der sie an "},{"p":"wissen-pacht.html","i":"i346","x":"II Wann versteigert wird Zu jedem Jahresbeginn würfelt die Stadt, frühestens 1408: mit einem Viertel Wahrscheinlichkeit kommt es zu einer Versteigerung — im Mittel also alle vier Jahre; nur, wenn gerade keine andere läuft; und nur, wenn die Stadt überhaupt noch eine der drei Stätten selbst besitzt. Unter denen, die ihr gehören, entscheidet das Los. Was einmal verkauft ist, kommt nicht wieder unter"},{"p":"wissen-pacht.html","i":"i347","x":"III Was die Stätte wert ist, und das Mindestgebot Jede Stätte trägt zwei Zahlen mit sich: ihren Wert und das letzte Gebot. Am Anfang ist der Wert der Gebäudewert — die Hütte samt Räumen, Anbauten und Inhalt —, und als „letztes Gebot“ steht das Doppelte davon da, obwohl nie jemand geboten hat. Daraus rechnet die Stadt das Mindestgebot: das letzte Gebot, plus ein Anteil von Wert und letztem Gebot zu"},{"p":"wissen-pacht.html","i":"i348","x":"IV Wer mitbieten darf Höchstens acht Bieter. Zugelassen ist nur, wer in bar mindestens das Mindestgebot besitzt — Waren, Häuser und Schuldscheine zählen nicht — und wer nicht im Kerker sitzt. 1. Zuerst kommen alle Spieler, Menschen wie Mitspieler im Netz, die die Bedingungen erfüllen. 2. Die freien Plätze füllen dann die Computerdynastien und die wohlhabenden Bürger der Stadt auf — die reichsten z"},{"p":"wissen-pacht.html","i":"i349","x":"V Fünf Runden, ein Gulden Aufschlag Die Versteigerung hat fünf Runden. In jeder Runde gibt jeder, der noch dabei ist, ein Gebot ab oder steigt aus — wer einmal passt, ist draußen. Das höchste Gebot wird zum neuen Preis; bei Gleichstand gewinnt, wer früher in der Reihe steht. Nach jeder Runde außer der letzten steigt der Preis um einen einzigen Gulden über das bisher höchste Gebot. Bieten nur noch "},{"p":"wissen-pacht.html","i":"i350","x":"VI Wie die Computer bieten Ein Computer wirft nicht sein ganzes Vermögen in die Waagschale. Er nimmt sich jede Runde aufs Neue einen Betrag vor: etwa 30 bis 47 Prozent seines Bargelds, ausgewürfelt; höchstens das Doppelte des aktuellen Preises. Liegt dieser Betrag unter dem Preis, steigt er aus. Sonst bietet er nur mit einer gewissen Wahrscheinlichkeit — je knapper der Preis an seiner Grenze liegt"},{"p":"wissen-pacht.html","i":"i351","x":"VII Wohin das Geld geht Fall Stadtkasse Pachtmeister Es gibt einen Pachtmeister, ein anderer gewinnt 90 % 10 % Der Pachtmeister ersteigert selbst 90 % — Das Amt ist unbesetzt 100 % — Das Zehntel steht so auch im Amtstext. Das schönste Detail ist die zweite Zeile: Ersteigert der Pachtmeister selbst, zahlt er nur neun Zehntel — sein eigener Anteil wird gar nicht erst überwiesen. Als Pachtmeister bek"},{"p":"wissen-pacht.html","i":"i352","x":"VIII Zurück an die Stadt Eine ersteigerte Stätte lässt sich nicht gewöhnlich verkaufen. Statt des Verkaufsknopfs bietet das Gebäudemenü an, sie an die Stadt zu verkaufen. Abreißen und Aufwerten stehen dort gar nicht erst im Menü. Ihr bekommt dafür die Hälfte von Wert und letztem Gebot zusammen. Wer die Mine für 8.200 Gulden ersteigert hat, bekommt also gut 5.260 zurück. Das Geld kommt dabei aus de"},{"p":"wissen-pacht.html","i":"i353","x":"IX Rohstoffe veredeln Waldstück, Steinbruch und Mine betritt man nicht wie ein Haus. Ein Doppelklick in der Stadt zeigt die Stätte von außen, mit ihren Stellen zum Anklicken: Lager, Transport, beim Steinbruch das Abbauen und Suchen. Die Kugel der Produktion dort öffnet ein eigenes Fenster, „Rohstoffe Veredeln“ — und nur hier, an diesen drei Orten. Im Stollen der Mine gibt es kein Veredeln. Lange w"},{"p":"wissen-leben.html","i":"i354","x":"I Zwei Zähler, nicht einer Jede Figur trägt zwei getrennte Größen. Die Lebenskraft ist die Kerze im Charakterbogen: Sie steht mit zwölf Jahren auf vollen 1000 Punkten und brennt danach jedes Jahr ein Stück herunter. Sie wächst nie von allein nach. Daneben gibt es die Wunden. Sie kommen von Schlägen, Duellen, Unfällen — und, was niemand vermutet, auch von Krankheiten. Wunden heilen von selbst, und "},{"p":"wissen-leben.html","i":"i355","x":"II Das Tempo steht bei der Geburt fest Gewürfelt wird nicht der Tod, sondern das Tempo: Jede Figur bekommt bei der Geburt ihr eigenes, festes Brenntempo von rund 24 bis 37 Punkten je Jahr. Daraus folgt ein Sterbealter zwischen etwa 39 und 54 Jahren — wenn nichts dazwischenkommt. Es gibt keinen Todeswurf. Es gibt nur eine Kerze, die bei jedem verschieden schnell brennt. Wie gut das stimmt, zeigt ei"},{"p":"wissen-leben.html","i":"i356","x":"III Kinder Unter zwölf Jahren brennt gar nichts: Die Kerze jedes Kindes steht auf vollen 1000, und erst mit dem zwölften Geburtstag beginnt sie zu sinken. Dafür ist ein Kind zerbrechlich. Seine Widerstandskraft wächst von einem Viertel bis zwei Fünfteln bei der Geburt gleichmäßig auf den vollen Wert mit zwölf. Der Charakterbogen zeigt trotzdem eine volle Kerze — sichtbar wird der Unterschied erst,"},{"p":"wissen-leben.html","i":"i357","x":"IV Das Dach über dem Kopf verlängert das Leben Das ist der größte Hebel, den man selbst in der Hand hat — und im Spiel steht er nirgends. Die Ausbauten der Wohnstätte (offenes Feuer, Kamin, Vertäfelung, Tapeten, Wintergarten) bringen Punkte, und jeder volle Ausbau senkt das jährliche Brennen. Wohnstätte Punkte weniger Brennen je Jahr keine 0 — Haus 20 ¾ Bürgerhaus 30 1⅛ Villa 50 1⅞ Palazzo 80 3 Be"},{"p":"wissen-leben.html","i":"i358","x":"V Neun Krankheiten, und sie vergehen von selbst Pest, Ruhr, Lungenentzündung, Husten, Haarausfall, Angst im Dunkeln, Vergesslichkeit, Lachanfall, Knochenbruch. Jede hat eine Schwere, keinen bloßen Ja-Nein-Zustand, und man kann an mehreren zugleich leiden. Beim Ausbruch schlägt die Krankheit einmal zu, und zwar als Wunde, nicht als Verlust an der Kerze. Eine schwere Pest reißt eine Wunde von bis zu"},{"p":"wissen-leben.html","i":"i359","x":"VI Wie man überhaupt krank wird Es gibt sieben Wege. Von selbst geschieht es nur auf dreien: Weg wen es trifft wie oft Zufall des Jahres, schwerer nur Euch, nicht die Gegner zusammen gut 4 % je Runde Zufall des Jahres, leichter nur Euch, nicht die Gegner (in den 4 % enthalten) Siechtum in der Stadt nur, wer kein Dach hat 5 % je Jahr Die Pest Arbeiter, Meister, Hausherr nach der Stadtchronik oder d"},{"p":"wissen-leben.html","i":"i360","x":"VII Woher die Pest kommt Die Pest ist eine der drei Katastrophen, die die ganze Stadt treffen — neben dem Großbrand und dem Wirbelsturm. Zu ihr führen zwei Wege: Die Chronik der Stadt schickt sie an festen Jahren — sechsunddreißigmal in den sechzehn Chroniken des Spiels — und legt fest, wie viele Häuser sie heimsucht: eines bis zehn. Ein eigener Würfel der Stadt schickt dazu alle paar Jahre eine K"},{"p":"wissen-leben.html","i":"i361","x":"VIII Wunden heilen, und zwar schnell Anders als die Kerze erholen sich Wunden von allein: jede Stunde um elf Prozent, zwischen sechs Uhr morgens und zehn Uhr abends. nach bleibt von der Wunde einer Stunde 89 % acht Stunden 39 % einem Spieltag 15 % zwei Spieltagen 2 % Eine Wunde von 100 Punkten ist nach gut anderthalb Tagen restlos fort. Wer also ein Duell oder einen Pestausbruch überlebt hat, brau"},{"p":"wissen-leben.html","i":"i362","x":"IX Was wirklich hilft Mittel was es bringt Medicus heilt die halbe Wundenlast — aber nur in der Hälfte der Fälle Elixier des Dr. Faustus ein Zehntel dessen, was von der Kerze noch übrig ist Kräuterschnaps mildert eine einzige Krankheit, die erste in der Reihe von der Pest an Wohnstätte bis zu sechs Jahre, wenn sie in gutem Zustand ist Versicherungsbulle holt Euch einmal nach dem Tod zurück — für v"},{"p":"wissen-leben.html","i":"i363","x":"X Wer sonst noch stirbt Bürger ohne Beruf. Ein Städter, der nie ein Handwerk und nie ein Amt hatte, stirbt mit 44 bis 47 Jahren — ganz gleich, wie viel Kerze er noch hat. Eure eigene Familie ist davon ausgenommen, die der Gegner nicht. Waisen in einer übervollen Stadt. Ist die Stadt zu 85 Prozent voll, sterben auch ungeschützte Waisen, gleich welchen Alters. In den gemessenen Partien wurde diese G"},{"p":"wissen-leben.html","i":"i364","x":"XI Vier Dinge, die anders sind, als sie aussehen Der Hauch des Verfalls verjüngt sein Opfer. Die Kunst des Totengräbers soll dem Opfer Jahre stehlen — tatsächlich setzt sie dessen Kerze auf volle 1000 zurück. Wer sie einsetzt, schenkt seinem Feind ein neues Leben. So steht es im Programm; am laufenden Spiel beobachtet ist es nicht. Und die Séance ebenso. „Je größer Euer Wunsch, um so mehr Lebenskr"},{"p":"wissen-werbung-und-ehe.html","i":"i365","x":"I Das Werben selbst kostet nichts „Um Ehepartner werben“ ist die billigste Handlung des ganzen Menüs: kein Aktionspunkt, keine Gebühr, kein Gulden. Verlangt wird nur, daß Ihr ledig seid — oder verwitwet. Wessen Gatte gestorben ist, darf sofort von neuem freien. Bezahlt wird genau eines, und das freiwillig: das Geschenk. Auch die Hochzeit kostet nichts. Die „Gebühr für Hochzeiten“, die im Kirchenme"},{"p":"wissen-werbung-und-ehe.html","i":"i366","x":"II Wie lange es dauert Die Dauer liegt zwischen 2 und 15 Jahren und setzt sich aus vier Posten zusammen: Posten Jahre ihr Alter: mit 15 Jahren +1 … mit 30 und älter −3 wie gut sie von Euch denkt — von ganz bis gar nicht +1 bis +6 ist sie reicher als Ihr? +1 bis +6 ihre Begabung (alle Talente zusammen) 0 bis +5 Zwischen 15 und 30 fällt der Altersposten gleichmäßig. Beim Vermögen zählt das der Umwor"},{"p":"wissen-werbung-und-ehe.html","i":"i367","x":"III Was „sie mag Euch“ wirklich heißt Der Posten „wie gut sie von Euch denkt“ ist Euer Ansehen bei ihr, und das Spiel rechnet es jedes Jahr frisch. Es setzt sich nicht nur aus der Zuneigung zusammen, sondern auch aus Dingen, an die man beim Freien nicht denkt: Euer Haus und Eure Ämter- und Zunftgebäude machen Eindruck. Der Glaube. Teilt sie Euren, steht Ihr ein paar Punkte besser da, sonst ein paa"},{"p":"wissen-werbung-und-ehe.html","i":"i368","x":"IV Neun Namen, und jedesmal andere Das Auswahlfenster zeigt neun Personen, drei mal drei, und unter jedem Namen die Werbedauer in Jahren. Gezogen werden sie bei jedem Öffnen neu aus der ganzen Stadt, gleichmäßig und ohne Vorliebe. Wer nicht zufrieden ist, macht das Fenster noch einmal auf. Gefällt Euch keiner der neun, oder ist jede Werbung zu lang: Fenster schließen und wieder öffnen. Es kostet n"},{"p":"wissen-werbung-und-ehe.html","i":"i369","x":"V Das Jahr der Werbung Einmal im Jahr, morgens um acht, rückt die Werbung voran: Wer wirbt je Jahr Ihr selbst 1 Jahr ein Haus der Konkurrenz 2 bis 3 Jahre ein Bürger der Stadt 1, in jedem vierten Fall 2 Die Konkurrenz wirbt also zwei- bis dreimal so schnell wie Ihr — es sei denn, Ihr schenkt. Die Werbung bricht ab, wenn einer von beiden stirbt oder in den Kerker kommt, wenn die Umworbene einem and"},{"p":"wissen-werbung-und-ehe.html","i":"i370","x":"VI Ein Geschenk im Jahr Das erste Angebot liegt erst nach dem ersten verstrichenen Jahr an, nicht gleich beim Beginn. Danach gibt es jedes Jahr genau eines: drei Geschenke zur Wahl, dazu „Das ist alles zu teuer!“. Wer ablehnt, hat das Angebot dieses Jahres verbraucht. Wer das Fenster nicht aufmacht, verliert es auch: Im nächsten Jahr liegt ein neues da, das alte ist fort. Reicht das Bargeld nicht,"},{"p":"wissen-werbung-und-ehe.html","i":"i371","x":"VII Was ein Geschenk bringt Jedes Geschenk hat eine Stufe von 0 bis 31, und jede Umworbene einen Titel von 0 (Unfreie) bis 9 (Reichsfürstin). Entscheidend ist allein, wie weit die Stufe über ihrem Titel liegt: Stufe über ihrem Titel spart 0 oder 1 — oder darunter nichts 2 bis 4 1 Jahr 5 bis 7 2 Jahre 8 und mehr 3 Jahre Mehr als drei Jahre bringt kein Geschenk, wie teuer es auch sei. Und der Preis "},{"p":"wissen-werbung-und-ehe.html","i":"i372","x":"VIII Die Antwort verrät den Gewinn Das Spiel sagt nie, wieviel ein Geschenk gebracht hat. Die Umworbene sagt es: sie … gespart weiß nicht, ob das ernst gemeint ist · schaut Euch ungläubig an · ist irritiert · lächelt unsicher · murmelt „Danke!“ 0 ist damit zufrieden · ist glücklich · nickt zufrieden · freut sich über das Geschenk 1 haucht Euch einen Kuß zu 1 oder 2 ist begeistert · schaut Euch bew"},{"p":"wissen-werbung-und-ehe.html","i":"i373","x":"IX Die zweiunddreißig Geschenke Stufe Geschenk 0 Ein Schuldschein 1 Ein heißer Stein zum Wärmen 2 Ein Brotmesser 3 Eine Küchenschürze 4 Ein Strauß schöner Rosen 5 Euer Lieblingskochbuch 6 Ein wohlriechendes Duftwasser 7 Ein Leibeigener 8 Ein Strauß edler Rosen 9 Ein Ausflug aufs Land 10 Ein Keuschheitsgürtel 11 Eine uralte Schatzkarte 12 Ein altgedientes Reitpferd 13 Einige Leibeigene 14 Ein zügel"},{"p":"wissen-werbung-und-ehe.html","i":"i374","x":"X Welche Geschenke Ihr zu sehen bekommt Angeboten werden drei aus einer Leiter von zwölf aufeinanderfolgenden Stufen. Wo sie beginnt, hängt an Eurem Amt — oder an dem Eures Vaters, wenn das höher ist: je zwei Amtsstufen eine Geschenkstufe höher. Ihr Leiter ohne Amt Stufe 0 bis 11 mittleres Amt 3 bis 14 eines der allerhöchsten Ämter 6 bis 17 Wer sein Amt verliert, freit weiter in alten Kreisen. Wer"},{"p":"wissen-werbung-und-ehe.html","i":"i375","x":"XI Was ein Geschenk kostet Der Preis hängt am Vermögen beider Seiten — Bargeld, Häuser und Waren zusammen — und an der Stufe. Wer weniger als tausend Gulden besitzt, wird wie mit tausend gerechnet. Ungefähre Preise in Gulden: Vermögen Stufe 0 Stufe 11 Stufe 17 beide arm 3 37 56 Ihr 100.000, sie arm 157 1.894 2.840 beide 500.000 1.562 18.750 28.125 Jede Stufe höher kostet gleich viel mehr: Stufe 11"},{"p":"wissen-werbung-und-ehe.html","i":"i376","x":"XII Das Wettrennen Um dieselbe Person dürfen beliebig viele zugleich werben; niemand wird daran gehindert. In einer Kölner Partie warben drei Männer zugleich um dieselbe Wilhelmine, einer davon der Spieler. Wer zuerst sein Ziel erreicht, bekommt die Zusage. Alle anderen fallen im nächsten Jahr heraus. Vom Nebenbuhler erfahrt Ihr erst, wenn Ihr verloren habt. In den Spieldateien steht ein Gerücht: "},{"p":"wissen-werbung-und-ehe.html","i":"i377","x":"XIII Verlobung und Hochzeit Mit der Zusage sind beide verlobt, und die Umworbene zieht in den Haushalt dessen, der geworben hat — wirbt eine Frau, zieht der Mann zu ihr. Den Nachnamen behält jeder. Die Kinder gehören fast immer zum Haus des Vaters; bei einer Konkurrentin, die sich einen Bürger genommen hat, tragen sie aber ihren Namen und gehören zu ihrem Haus. Die Hochzeit folgt etwa zwei Stunden"},{"p":"wissen-werbung-und-ehe.html","i":"i378","x":"XIV Der Erbe kommt fast sofort Die Trauung hat eine Wirkung, die nirgends steht: Sie stellt die Frau knapp über die Schwelle zur Empfängnis. Heiratet ein Spieler oder ein Haus der Konkurrenz, kommt das erste Kind schon im Jahr nach der Hochzeit. Solange die Werbung läuft, wird die Frau nicht schwanger; beim Spieler gibt sie erst der Hochzeitsfilm frei. Danach wächst die Bereitschaft jedes Jahr von"},{"p":"wissen-werbung-und-ehe.html","i":"i379","x":"XV Die Stadt heiratet mit Auch Bürger und die Häuser der Konkurrenz werben — in einer Kölner Partie entstanden in neunzehn Jahren zwanzig Bürgerehen. Sie wählen anders als Ihr: aus zwölf Gezogenen, und nur unter denen, die sie zu mindestens dreißig Prozent mögen. Ein Bürger fragt sich höchstens jedes vierte Jahr, ob er freit. Geschenke machen sie keine; dafür sind sie schneller. Um Euch selbst wir"},{"p":"wissen-werbung-und-ehe.html","i":"i380","x":"XVI Die Scheidung Erlaubt ab dem Titel Freiherr, solange der Gatte lebt. Sie kostet acht Aktionspunkte — die teuerste Handlung des Menüs. Das Fenster nennt zwölf Prozent des Vermögens. Gezahlt werden acht, in bar, an den Gatten. Die vier Prozent, „damit die Kirche alle Augen zudrückt“, bekommt niemand. Gerechnet wird vom ganzen Vermögen, Häuser und Waren eingeschlossen, Schulden nicht abgezogen — "},{"p":"wissen-werbung-und-ehe.html","i":"i381","x":"XVII Die Geliebte Anders als bei der Ehe darf die Auserwählte verheiratet sein; ausgeschlossen ist nur, wer schon eine Liaison hat. Eine Absage gibt es nicht: Wer in der Liste steht, sagt ja, und Euer Ansehen bei ihr steigt deutlich. Die Liebschaft kostet jedes Jahr zwei Aktionspunkte. Entdeckt wird sie nie; erst wenn Ihr sie beendet, verliert Ihr einmalig an Ansehen bei ihr, um so mehr, je länger"},{"p":"wissen-werbung-und-ehe.html","i":"i382","x":"XVIII Acht Ratschläge Öffnet das Auswahlfenster mehrmals und nehmt den Namen mit der kürzesten Zahl darunter. Es kostet nichts. Das Alter der Braut ist ein Tausch. Ab dreißig ist sie drei Jahre schneller zu haben — aber mit 38 bekommt sie keine Kinder mehr, und die Werbung selbst dauert auch. Seid reicher als ihr Haus. Dann kostet das Vermögen nur ein Jahr statt bis zu sechs. Pflegt Euer Ansehen b"},{"p":"wissen-geruechte.html","i":"i383","x":"I Ein Zettel am Marktplatz Wer einen Nebenbuhler schlechtmachen will, ohne selbst die Stimme zu erheben, schreibt ein Pamphlet. Verfasst wird es in der Bibliothek Eures Wohnhauses: Ihr wählt das Opfer, bestätigt, und der Zettel hängt am Schwarzen Brett auf dem Marktplatz. Das Brett ist dort ein Klickziel wie die Marktstände; wer draufklickt, sieht die „Bekanntmachungen“. Was dort steht, sucht Ihr "},{"p":"wissen-geruechte.html","i":"i384","x":"II Vier Plätze — und ein Text, der flunkert Am Brett gibt es zwei Grenzen, und sie sind nicht dieselbe. Höchstens vier Pamphlete am ganzen Brett. Gezählt wird über die ganze Stadt, egal von wem und gegen wen. Das fünfte wird abgewiesen, mit der Meldung, es sei gerade kein Platz frei — reißt eines ab oder wartet. Höchstens vier eigene. Diese Grenze prüft schon das Menü, bevor Ihr überhaupt schreibt"},{"p":"wissen-geruechte.html","i":"i385","x":"III Was ein Pamphlet anrichtet Ein hängendes Pamphlet kostet das Opfer Gunst — und zwar bei jedem Bürger, der es liest, einzeln. Wie viel, hängt an zwei Rhetorik-Talenten: dem des Verfassers und dem des Lesers. Das des Opfers spielt keine Rolle. Rhetorik des Verfassers Leser ohne Leser ¼ Leser ½ Leser ¾ Leser voll ohne −4 −3 −2 0 +1 ein Viertel −4 −4 −3 −1 0 halb −6 −5 −4 −2 0 drei Viertel −7 −6 −"},{"p":"wissen-geruechte.html","i":"i386","x":"IV Wie weit ein Pamphlet reicht Ein Pamphlet hängt genau eine Runde — 24 Stunden Spielzeit. In dieser Zeit wirkt es nicht auf einen Schlag, sondern Stück für Stück: eine Minute nach dem Anschlagen der erste Durchgang; danach jede Stunde einer; je Durchgang kommen 16 Plätze der Stadtbevölkerung an die Reihe. Das Spiel führt die Leute der Stadt in einer Liste mit 768 Plätzen. Jedes Pamphlet beginnt "},{"p":"wissen-geruechte.html","i":"i387","x":"V Schutzkreuz, Tinte und andere Mittel Das Schutzkreuz. Trägt das Opfer beim Anschlagen ein Schutzkreuz, wird das Pamphlet sofort abgerissen. Das Opfer erfährt davon, der Verfasser auch. Geprüft wird das aber nur im Augenblick des Anschlagens. Für ein Pamphlet, das schon hängt, gibt es einen zweiten Weg: Wer das Kreuz anwendet, räumt damit alle laufenden Pamphlete gegen sich ab. Erst beide Wege zu"},{"p":"wissen-geruechte.html","i":"i388","x":"VI Der Zunftmeister und seine drei Kniffe Ganz andere Gerüchte streut, wer Vorsteher einer Zunft ist. Die vier Zünfte im Code sind Parfumeure, Schmiede, Steinmetze und Tischler; wer eines dieser Ehrenämter trägt, darf im Zunfthaus drei Maßnahmen ergreifen: Maßnahme Raum im Zunfthaus Ausbau nötig Aktionspunkte Warenpreise manipulieren Sekretariat — 3 Arbeiter aufwiegeln Halle ab Stufe 2 5 Politik S"},{"p":"wissen-geruechte.html","i":"i389","x":"VII Das Preisgerücht Der Menütext verspricht, Ihr könntet die Preise von zwei zufälligen Waren einer Berufsgruppe „erhöhen“ oder „verfallen lassen“. Zur Wahl stehen sieben Gewerke, jedes mit seinem Wappen: Schmiede, Steinmetze, Tischler, Wirtshäuser, Parfumeure, Alchimisten — und die Kirche. Händler, Geldleiher oder Wache sind nicht dabei; sie stellen nichts her, woran man drehen könnte. So geht d"},{"p":"wissen-geruechte.html","i":"i390","x":"VIII Arbeiter aufwiegeln Ihr wählt auf der Stadtkarte den Betrieb eines Konkurrenten — der eigene geht nicht — und bezahlt die Belegschaft dafür, dass sie ihrem Herrn gram wird. Die Summe ist ein Hundertstel Eures Vermögens, aber nie weniger als 160. Das Spiel prüft vorher, ob Ihr sie habt. Dann: Jeder Arbeiter des Betriebs verliert Gunst für seinen Arbeitgeber. Wie viel, sagt Eure Rhetorik und ei"},{"p":"wissen-geruechte.html","i":"i391","x":"IX Politik — je nach Zunft etwas anderes Die teuerste Maßnahme heißt bei jeder Zunft anders und tut auch anders: Zunft Überschrift was wirklich geschieht Schmiede, Tischler Zwist in einer Kammer säen in der gewählten Kammer verliert jeder bei jedem Gunst, in beide Richtungen; Ihr selbst bleibt außen vor Steinmetze Bewunderung erzeugen Eure Gunst steigt bei jedem Mitglied der gewählten Kammer Parfu"},{"p":"wissen-geruechte.html","i":"i392","x":"X Wie das Zunfthaus wächst — und wer es bezahlt Das Zunfthaus hat drei Stufen: Handwerkshaus, Zunfthaus, Gildensitz. Den Ausbau besorgt der Zunftmeister selbst — im Spiel heißt er Gildenmeister —, und zwar über dasselbe Gebäudemenü wie bei einem Betrieb: „Gebäude um eine Stufe aufwerten“. Ein eigenes Menü im Zunfthaus gibt es dafür nicht. Das Menü bekommt nur er. Klickt ein anderer auf das Zunftha"},{"p":"wissen-geruechte.html","i":"i393","x":"XI Im Nachbau Was davon schon steht. Das Pamphlet rechnet seit Oktober nach den Regeln oben: vier Plätze, die Gunstformel mit Tinte, eine Runde Laufzeit. Das Schwarze Brett am Marktplatz ist anklickbar, Abreißen inklusive. Vom Zunftmeister steht das Preisgerücht samt seiner Tafel; Aufwiegeln und Politik warten noch auf ein Zunfthaus, das ausgebaut werden kann."},{"p":"wissen-steuern.html","i":"i394","x":"I Fünf Abgaben, einmal im Jahr Das Spiel kennt fünf Abgaben: Umsatzsteuer, Gildensteuer, Importzoll, Erbschaftsteuer und den Kirchenzehnt. Keine davon wird beim einzelnen Verkauf fällig. Alle werden einmal im Jahr abgerechnet, am Beginn der neuen Runde, und zwar grundsätzlich für jede Figur der Stadt — für Euch genauso wie für Eure Gegner. Die Rechnung ist für alle fünf dieselbe: Grundlage mal Ste"},{"p":"wissen-steuern.html","i":"i395","x":"II Umsatzsteuer oder Gildensteuer — nie beides Grundlage beider Steuern ist derselbe Betrag: alles, was Ihr im Lauf des Jahres verkauft habt. Gezählt wird der Erlös des Verkäufers, nicht der Einkauf. Nach der Abrechnung fängt die Summe wieder bei null an. Welche der beiden Steuern Ihr zahlt, entscheidet Euer Gewerk. Nur vier Gewerke haben eine Zunft: Schmiede, Steinmetze, Tischler und Parfumeure. "},{"p":"wissen-steuern.html","i":"i396","x":"III Der Zoll, der nichts vergißt Der Importzoll trifft nicht den Einkauf am Markt. Das, was Ihr am Markt kauft und verkauft, fällt unter die Umsatzsteuer. Grundlage des Zolls ist allein der Handel über die Import- und Exportlager, und zwar beide Seiten des Geschäfts gleich. Und dann folgt die eigentliche Überraschung: Diese Summe wird nie zurückgesetzt. Die Umsatzsteuer fängt jedes Jahr bei null a"},{"p":"wissen-steuern.html","i":"i397","x":"IV Die Erbschaftsteuer — wer knapp ist, zahlt nichts Stirbt das Haupt Eurer Familie und übernimmt ein Erbe, wird einmal Erbschaftsteuer fällig. Grundlage ist das ganze Vermögen des Verstorbenen: Bargeld, Gebäude und alles, was darin lagert. Bezahlt wird aber nur aus dem Bargeld des Erben. Und reicht das nicht für die volle Summe, zahlt er gar nichts. Die Steuer wird weder gestückelt noch gestundet"},{"p":"wissen-steuern.html","i":"i398","x":"V Der Kirchenzehnt gehört niemandem Die Umsatzsteuer, die Gildensteuer, den Zoll und die Erbschaftsteuer bekommt die Stadtkasse. Den Kirchenzehnt bekommt niemand. Weder der Bischof noch die Kirche noch die Stadt. Das Geld wird Euch abgezogen und verschwindet. Wer hätte das gedacht. Die anderen vier Abrechnungen schlagen zuerst die Stadtkasse auf. Die des Zehnts läßt genau diesen einen Schritt aus "},{"p":"wissen-steuern.html","i":"i399","x":"VI Die Miete der Arbeiter Eine sechste Abgabe zahlt Ihr nicht selbst: die Miete der Arbeiter. Jeder Arbeiter, der in einer Arbeiterunterkunft wohnt, zahlt einmal im Jahr an die Stadtkasse. Wie viel, hängt am Mietpreisniveau, das der Rat festlegt: Mietpreisniveau sehr hoch hoch mittel niedrig lausig Miete im Jahr 14 13 12 11 10 Die Miete geht immer an die Stadt. Auch dann, wenn die Unterkunft einem"},{"p":"wissen-steuern.html","i":"i400","x":"VII Was die Ämter einbringen Jedes Amt bringt ein festes Jahreseinkommen. Der Amtstext nennt es eine Aufwandsentschädigung, den Betrag aber nennt er nicht. Hier ist er: Ebene untere Stufe mittlere Stufe Spitze Stadtdiener, Schergen, Informanten 500 700 1.000 Stadtrat 2.000 2.500 3.000 Kirche 2.000 2.500 3.000 Land 5.000 7.000 10.000 Reich 20.000 30.000 50.000 Im Stadtrat bekommen also Baumeister, "},{"p":"wissen-steuern.html","i":"i401","x":"VIII Die Pacht und der Anteil des Pachtmeisters Eine Jahrespacht gibt es nicht. Pachtgüter werden versteigert, im Mittel etwa alle vier Jahre. Vom Zuschlag bekommt die Stadt 90 % und der Pachtmeister 10 %. Ist das Amt unbesetzt, geht alles an die Stadt. Ersteigert der Pachtmeister selbst, zahlt er nur die 90 % an die Stadt, seinen eigenen Zehnten spart er sich. Ob diese Teilung auch dann läuft, we"},{"p":"wissen-steuern.html","i":"i402","x":"IX Wohin die Gebühren gehen — fast immer ins Nichts Neben den Steuern zahlt Ihr ständig für Dienste. Fast all dieses Geld bekommt niemand: Bauen, Aufwerten und Ausbauen: Das Geld verschwindet. Im Gesetzestext steht, das Baugeld sei „an die Stadt abzuführen\", doch eine Buchung steht nicht dahinter. Aufwerten kostet drei Zehntel des Grundpreises der nächsten Stufe. Karren kaufen und ausbessern, Reno"},{"p":"wissen-steuern.html","i":"i403","x":"X Die Stadtkasse wird nie leer Was fließt also in die Stadtkasse? Umsatz- und Gildensteuer, Zoll, Erbschaftsteuer, die Miete der Arbeiter, der größte Teil der Pacht und das Geld für das Bürgerrecht. Keine der hier beschriebenen Zahlungen geht aus ihr heraus — selbst die Amtsgehälter kommen woanders her. Trotzdem kann die Kasse nicht leer werden. Fällt der Bestand unter 160.000 Gulden, bekommt die "},{"p":"wissen-titel-und-aemter.html","i":"i404","x":"I Ein Klick auf den eigenen Namen Oben im Banner steht Euer Name, und kaum jemand klickt ihn an. Dahinter liegt das Fenster „Eure Privilegien“ — die Liste von allem, was Euch Titel und Amt erlauben. Das Spiel kennt genau 58 Vorrechte, und für jedes prüft es eine eigene Regel, ob Ihr es gerade habt. Die Liste ändert sich deshalb, während Ihr spielt: Sie fragt jede halbe Sekunde neu nach. Es gibt zw"},{"p":"wissen-titel-und-aemter.html","i":"i405","x":"II Grau heißt: Ihr werdet erpreßt Eine Zeile wird nur aus einem einzigen Grund grau: Jemand erpreßt Euch. Dann bleiben alle Handlungen Eures Amtes sichtbar, aber gesperrt — vier Jahre lang, so lange hält eine Erpressung. Für jede Amtshandlung fragt das Spiel in derselben Reihenfolge: Habt Ihr das Amt? Werdet Ihr erpreßt? Habt Ihr es diese Runde schon getan? Und umgekehrt: Wer selbst jemanden erpre"},{"p":"wissen-titel-und-aemter.html","i":"i406","x":"III Was der Titel bringt Titel was dazukommt Herr, Bürger das einfache Wohnhaus Patrizier das Bürgerhaus; Furcht einflößen und Beleidigen Edelmann die Villa, ein Leibwächter, 50 % mehr Kredit Freiherr der Palazzo, ein zweiter Leibwächter, die Scheidung Graf 100 % mehr Kredit, und Werbung um eine Braut dauert nur halb so lang Ein Wohnsitz verschwindet aus der Liste, sobald der nächste erreicht ist "},{"p":"wissen-titel-und-aemter.html","i":"i407","x":"IV Was jedes Amt darf Die Ämter der Stadt, der Kirche und des Landes bringen ihre eigenen Vorrechte mit. Die stillen: Amt stilles Vorrecht Richter, Bürgermeister, Bischof, Landesherr Immunität — gegen Euch kann niemand Anklage erheben Pachtmeister ein Anteil an der Pacht Baumeister, Kämmerer billiger bauen Kerkermeister Folter vortäuschen, Gefangene vorzeitig entlassen Inquisitor, Großinquisitor, "},{"p":"wissen-titel-und-aemter.html","i":"i408","x":"V Becircen: der Rang des Hauses zählt Becircen bringt Gunst, und zwar genau so viele Punkte, wie Ihr einsetzt, mal (10 + Rang Eures Hauses − Rang ihres Hauses). Bei gleichem Rang bringt jeder Punkt also zehn Gunst; steht Euer Haus höher, mehr. Das Spiel prüft übrigens erst nach der Wahl, ob die Person das richtige Geschlecht hat. Die Liste zeigt alle, und wer daneben greift, bekommt eine höfliche "},{"p":"wissen-titel-und-aemter.html","i":"i409","x":"VI Haß säen und Frieden stiften Der Großinquisitor wählt zwei Menschen und macht sie zu Feinden. Das kostet vier Punkte und zwei Prozent ihrer beiden Vermögen zusammen — zwei reiche Leute zu verfeinden, ist teuer. Die Zuneigung beider zueinander fällt dabei tief ins Minus; wie tief genau, hängt an einer Stelle, die nicht ganz nachgeprüft ist. Das Gegenstück hat der Landesherr: Frieden stiften. Bei"},{"p":"wissen-titel-und-aemter.html","i":"i410","x":"VII Einschmeicheln und Rauswurf — der Reichskanzler Der Reichskanzler hat die zwei stärksten Handlungen des Spiels. Einschmeicheln kostet nichts, weder Punkte noch Geld: Ihr gewinnt bei einem Amtsträger 100 Punkte Zuneigung — und bei jedem anderen Mitglied seiner Kammer verliert Ihr 20. Einmal je Runde. Amtsrauswurf kostet 8 Punkte, und der Sitz ist frei. Auch einmal je Runde. Der Rausgeworfene be"},{"p":"wissen-titel-und-aemter.html","i":"i411","x":"VIII Unterschlagung und Bekehren Der Kämmerer nimmt einmal je Runde Geld aus seinem Amt: zwischen einem Achtel und fast dem ganzen Jahreseinkommen dieses Amtes, ausgewürfelt. Der Text sagt, das Geld komme aus der Stadtkasse. Das stimmt im Original nicht. Die Stadtkasse merkt nichts — das Geld kommt von niemandem. Im Nachbau kommt es wirklich aus der Stadtkasse, und höchstens so viel, wie darin ist"},{"p":"wissen-titel-und-aemter.html","i":"i412","x":"IX Die sechs Wunder Der Erzbischof setzt vier Punkte ein, und das Spiel würfelt eines von sechs Wundern, jedes gleich wahrscheinlich. Alle Spieler lesen davon: Wunder was geschieht Madonna eine Kirche wird Wallfahrtsort; ihr Besitzer bekommt 2 bis 4 % seines Vermögens Gesundheit jeder schwer Verwundete hat eine Chance von eins zu zwei, daß seine Wunden heilen Blitzschlag ein fremdes Gebäude verlie"},{"p":"wissen-titel-und-aemter.html","i":"i413","x":"X Erpressung Erpressen darf jeder, ganz ohne Amt — aber immer nur einen zur Zeit, und nicht jeden. Das Spiel prüft der Reihe nach: zwei Aktionspunkte, wird die Person schon erpreßt, und habt Ihr drei offene Beweise gegen sie. Erst dann kommt die Frage. Ob es gelingt, entscheidet ein Wurf von 0 bis 7: Er darf nicht über der Zahl aller Beweise liegen, die Ihr gegen die Person habt. Beweise gelingt 3"},{"p":"wissen-titel-und-aemter.html","i":"i414","x":"XI Anklage und Abbitte Anklage erheben kostet nichts — kein Geld, keinen Punkt. Das Beweisbuch zeigt, wer was gegen wen in der Hand hat, und für jede Tat das Gesetz mit so vielen Paragraphenzeichen, wie schwer sie wiegt. Ohne einen offenen Beweis bleibt der Knopf gesperrt; hat der Beschuldigte Immunität, steht dort „Amtsimmunität“. Ab drei Beweisen kommt bei der Verhandlung auch der Kerkermeister "},{"p":"wissen-titel-und-aemter.html","i":"i415","x":"XII Medicus und Werbung Zwei Vorrechte hat fast jeder. Den Medicus aufzusuchen, kostet zwei Aktionspunkte und zwei Prozent Eures Vermögens — und im Original gelingt die Behandlung nur in der Hälfte der Fälle; nur dann zahlt Ihr und werdet geheilt. Um eine Braut werben kostet gar nichts. Das Fenster zeigt bis zu neun Kandidaten mit Bild und der Zahl der Jahre, die die Werbung dauern wird. Mehr dazu"},{"p":"wissen-schenke.html","i":"i416","x":"I Wer Gast ist — und wann gezählt wird Den ganzen Tag gehen Leute in Eure Schenke ein und aus. Gezählt wird davon nur, wer abends um halb elf dort steht. Einmal am Spieltag — und ein Spieltag ist eine ganze Runde — geht das Spiel die Leute der Stadt durch: die eine Hälfte um 22:30, die andere um 22:45, eine halbe Stunde bevor die Schenke um 23 Uhr schließt. Wer um Mittag dort saß und wieder ging, "},{"p":"wissen-schenke.html","i":"i417","x":"II Welche Schenke er wählt — Ausstattung gegen Weg Unter allen Schenken der Stadt nimmt der Arbeiter die mit dem besten Wert aus zwei Teilen: wie nah sie an seiner Wohnung liegt, und wieviel „Gästeaufkommen“ ihre Ausstattung trägt. Beide Teile sind gleich schwer: Die volle Ausstattung wiegt so viel wie der ganze Weg quer durch die Stadt. Stück Schenke Wirtshaus Gasthaus Schöne Stühle 15 15 15 Eise"},{"p":"wissen-schenke.html","i":"i418","x":"III Was ein Gast kauft und zahlt Im Schankraum verkauft Ihr genau zwei Dinge: Körnermahlzeit und Dünnbier, und nur, was in der Lagerfläche liegt. Starkbier, Fahnenbräu, Schädelbrand und Kräuterschnaps fragt kein Gast an — die sind Marktware. Der Schankpreis ist das Anderthalbfache des Marktpreises in der Stadt. Jeder Gast kauft ein Stück: Kann er sich das Teurere leisten und liegt beides da, wirft"},{"p":"wissen-schenke.html","i":"i419","x":"IV Warum die Schenke in den ersten Jahren eine Garküche ist Ob ein Arbeiter sich etwas leisten kann, hängt an dem, was er in der Tasche trägt. Gemessen in den Spielständen, mit den billigsten und teuersten Preisen, die je vorkamen: Jahr Bargeld eines Arbeiters (Mitte) kann die Mahlzeit zahlen kann das Dünnbier zahlen 1404 279 52 – 69 % 0 – 8 % 1405 357 67 – 88 % 0 – 14 % 1412 560 81 – 93 % 33 – 65"},{"p":"wissen-schenke.html","i":"i420","x":"V Das Würfelspiel „17“ — wann überhaupt jemand am Tisch sitzt Der Spieltisch (70 Gulden, schon in der Schenke) bietet ein Würfelspiel gegen einen Fremden. Ohne ihn steht an seiner Stelle ein Fass als Tisch, und gewürfelt wird nicht. Ob einer dasitzt, ist an drei Dinge gebunden: Es muß nach 12 Uhr sein. Euer Vermögen — Bargeld plus Wert Eurer Gebäude — muß mindestens 10.000 Gulden betragen. Darunte"},{"p":"wissen-schenke.html","i":"i421","x":"VI Wie die Würfel schummeln — nach Talent Die Regeln im Spieltext stimmen: drei Würfel verdeckt, Dreierpasch gewinnt sofort, dann weiterwürfeln oder stehenbleiben, beides mit Erhöhung, wer 18 erreicht, verliert, bei Gleichstand gewinnt die Bank. Was der Text nicht sagt: Die Würfel sind nicht fair. Bei Nacht und Nebel — das Talent, das die Hilfe nennt — verbiegt jeden Würfel: Euer Talent Eins Sechs"},{"p":"wissen-schenke.html","i":"i422","x":"VII Der Gegner gibt nie auf — und sein Geld gibt es nicht Aufgeben tut der Fremde nie. Das Spiel hat einen Weg dafür vorgesehen, aber die Bedingung kann nie erfüllt werden. Wartet also nicht darauf, daß er die Nerven verliert. Er zieht nach einer festen Regel: Fehlen ihm mehr als fünf bis zur 17, würfelt er immer; sonst wagt er es umso eher, je mehr noch fehlt. Schwache Gegner wagen mehr als stark"},{"p":"wissen-schenke.html","i":"i423","x":"VIII Die Dunkle Ecke — der Spion des Wirts Die Dunkle Ecke (100 Gulden, ab dem Wirtshaus) gehört dem Wirt, und nur er kann sie in Gang setzen: einmal im Jahr schickt er von dort einen Spion los. Der geht durch die Stadt und horcht in fünf bis acht Häusern herum. Im ersten findet er immer etwas; ob er in den weiteren fündig wird, hängt am Talent Bei Nacht und Nebel des jeweiligen Hausherrn. Nach dr"},{"p":"wissen-schenke.html","i":"i424","x":"IX Der Stammtisch Der Stammtisch (400 Gulden, nur im Gasthaus) hat vier Plätze, und man sitzt an höchstens einem in der ganzen Stadt. Die Runde beginnt mit dem fertigen Bau. Nicht beim Kauf, sondern wenn der Stammtisch nach seiner Bauzeit im Haus steht, richtet das Spiel die Tischrunde ein; eine Stunde später läuft sie zum ersten Mal, die erste Zeche fällt auf den folgenden Abend. Danach bleibt si"},{"p":"wissen-schenke.html","i":"i425","x":"X Was es nur im Hilfetext gibt Der Text verspricht Im Spiel Würfeln gegen einen oder mehrere Konkurrenten Gibt es nicht. Es gibt nur den Fremden; ein Spiel gegen Mitspieler hat das Programm nirgends. Zimmer vermieten Kein Menü dafür. Die Zimmertafel im Schankraum ist Kulisse. Einzeltische senken das Risiko einer Kneipenschlägerei Eine Schlägerei startet niemand; die Szenen liegen im Archiv, kein A"},{"p":"wissen-schenke.html","i":"i426","x":"XI Kleinigkeiten, die man nicht sieht Frauen dürfen eine Schenke führen, wie jedes andere Gewerbe auch. Wirte haben keine Zunft und kein Zunfthaus. Der Lohn des Schankpersonals ist derselbe wie überall: 112 Gulden für den Gesellen, 56 für den Lehrling je Runde, bei mittlerem Lohnniveau. Die Schenke hat Platz für 2, das Wirtshaus für 3, das Gasthaus für 4 Leute. Geöffnet ist von 12 bis 23 Uhr. Ein "},{"p":"wissen-altern-lassen.html","i":"i427","x":"I Worum es geht Vom Friedhof aus — der Hilfetext sagt: „von den Ruinen aus“ — schickt Ihr einen Eurer Gehilfen in die Stadt. Er sucht eine bestimmte Person, berührt sie, und sie soll „um einige Jahre“ altern. Im Menü heißt die Aktion „Jemanden altern lassen“, in der Überschrift Hauch des Verfalls. Kosten 4 Aktionspunkte — geprüft und auch abgezogen. Kein Geld Trefferaussicht ein Vergleich im Talen"},{"p":"wissen-altern-lassen.html","i":"i428","x":"II Der Ablauf Der Auftrag läuft in fünf Schritten: Losschicken. Ihr lest, Euer Gehilfe „macht sich murrend auf den Weg“. Suchen. Das Opfer wird dort gesucht, wo es wohnt — sonst an seiner Arbeitsstelle, sonst irgendwo. Ist es nicht zu finden, endet der Auftrag. Berühren. Hier fällt die Entscheidung: der Wurf gegen die Aussicht und, bei Erfolg, die Rechnung der Jahre. Zurückkehren. Berichten. Ihr e"},{"p":"wissen-altern-lassen.html","i":"i429","x":"III Was es kostet Vier Aktionspunkte. Das Menü prüft, ob Ihr sie habt, und der Auftrag zieht sie beim Start tatsächlich ab. Gulden kostet es nicht — weder der Spielerweg noch der Weg, den die Gegner gehen. Dasselbe gilt am Friedhof für das Erschaffen und Verbessern von Gehilfen, die Séance und die Heimsuchung: Dort zahlt Ihr mit Aktionspunkten, nicht mit Geld."},{"p":"wissen-altern-lassen.html","i":"i430","x":"IV Die Trefferaussicht Es gibt keinen Grundwert. Die Aussicht ist ein Vergleich im Talent Bei Nacht und Nebel — mit derselben Formel, die das Spiel für alle seine Übergriffe benutzt, von der Sabotage bis zum Anschwärzen. Mit a als Talent des Gehilfen und v als Talent des Opfers, beide von 0 bis 1: Aussicht = 0,2·a² + 0,3·a − 0,2·v − 0,3·v² + 0,5 Die Anzeige zeigt höchstens sechs Sterne, in halben "},{"p":"wissen-altern-lassen.html","i":"i431","x":"V Wie viele Jahre gestohlen werden Die Zahl hängt nicht am Gehilfen, sondern am Friedhof: an seinem baulichen Zustand und an seiner Ausbaustufe. Dazu kommt ein Wurf von 0 bis 2. Friedhof Ausbau bringt Zustand unter 50 % 50 bis 99 % 100 % Totenfeld +2 2 bis 4 3 bis 5 4 bis 6 Gottesacker +4 4 bis 6 5 bis 7 6 bis 8 Friedhof +6 6 bis 8 7 bis 9 8 bis 10 Eine Ausbaustufe ist zwei Jahre wert, ein gepfleg"},{"p":"wissen-altern-lassen.html","i":"i432","x":"VI Was beim Opfer geschieht Jede Figur trägt eine Lebensuhr, die mit den Jahren abläuft. Der Hauch greift in sie ein — aber verkehrt herum. Ein Fehler des Originals. Das Spiel reicht die gestohlenen Jahre an eine Stelle weiter, die ein Lebensalter erwartet und die Uhr auf dieses Alter stellt, statt etwas abzuziehen. Jedes Alter unter zwölf heißt dort: Uhr auf den vollen Anfangswert. Und der Hauch "},{"p":"wissen-altern-lassen.html","i":"i433","x":"VII Der Gehilfe Geschickt wird der erste Gehilfe, den das Spiel in seiner Figurenliste findet — ohne Vergleich der Talente. Wer mehrere hat und nur einen geschult, kann nicht steuern, wer geht. Nach einem Treffer hängt der Bericht manchmal einen zweiten Satz an: Euer Gehilfe sei „ebenfalls ein Opfer der Alterung geworden“. Wie oft, richtet sich nach seinem Talent in Handwerkskunst. Die Meldung ver"},{"p":"wissen-altern-lassen.html","i":"i434","x":"VIII Die Meldungen An wen Wann Was Opfer getroffen „Das Alter holt Euch ein…“ — mit einer von drei Wendungen Opfer entkommen „Eine gruselige Begegnung…“ Ihr Erfolg der Gehilfe kehrt zurück, am „freudigen Grunzen“ zu erkennen Ihr Fehlschlag er „traut sich nicht, Euch anzusehen“ Die drei Wendungen der Erfolgsmeldung — Haut, Haarpracht, Knochen — werden ausgewürfelt. Sie sagen nichts darüber, wie vie"},{"p":"wissen-altern-lassen.html","i":"i435","x":"IX Die Sperre und das Gesetz Wer es zweimal gegen dieselbe Person versucht, liest „in dieser Runde bereits“. Das Programm prüft aber nicht die Runde, sondern ob Euer letzter Auftrag gegen sie noch läuft. Ist der Gehilfe zurück, geht der nächste — auch in derselben Runde. Schon beim Losschicken legt das Spiel die Tat als Nekromantie an; ob sie als Tat zählt, prüft es dabei gegen das Stadtgesetz. Zu"},{"p":"wissen-altern-lassen.html","i":"i436","x":"X Wie wehrhaft die Opfer sind Ausgezählt an allen 302 Figuren einer Stadt im Jahr 1419 und ihren fünf Talenten: Gut die Hälfte aller Werte (53 %) zeigt höchstens anderthalb Sterne. Der Mittelwert liegt bei gut zwei Sternen, die Mitte der Reihe bei anderthalb. Die einfachste Figurenart, zu der die Arbeiter gehören, kommt im Mittel auf knapp anderthalb Sterne; einige andere Arten kommen auf rund dre"},{"p":"wissen-kabinett-und-kanone.html","i":"i437","x":"I Zwei Zimmer im Schloß Wer ein Schloß besitzt, kann darin zwei besondere Räume einrichten: den Kanonenturm und das Geheimkabinett. Beide baut Ihr über das Fenster „Räume\", beide brauchen zwölf Stunden Bauzeit. Raum Preis wo Kanonenturm 7.500 Burg und Schloß Geheimkabinett 15.000 nur im Schloß Den Menüpunkt „Räume\" gibt es erst bei einem Wohnsitz, der mindestens zwei solche Zimmer fassen darf — di"},{"p":"wissen-kabinett-und-kanone.html","i":"i438","x":"II Das Kabinett: vier Aufträge, nicht mehr Im Kabinett stehen genau vier Dinge zur Wahl: Vergiften — Ihr wählt ein Opfer und die Schwere des Giftes; Spione ausschalten — ohne Opfer, Ihr wählt nur, wie gründlich gesucht wird; Beweise fälschen — Ihr wählt ein Opfer und die Schwere des Verbrechens; Schleichende Lähmung — Ihr wählt ein Opfer, sonst nichts. Die ersten drei haben einen Regler mit drei S"},{"p":"wissen-kabinett-und-kanone.html","i":"i439","x":"III Was die vier Aufträge kosten Die Preise hängen an zwei Dingen: am Rang des Amtes, das das Opfer bekleidet, und am Vermögen — Eurem, und beim Fälschen und Lähmen auch dem des Opfers. Auftrag Gulden Aktionspunkte Vergiften keine Amtsrang/3, dazu 5 · 7 · 10 je nach Stufe Spione ausschalten 1 · 1,5 · 2 % Eures Vermögens keine Beweise fälschen 1 · 1,5 · 2 % beider Vermögen zusammen (Amtsrang/3 + 2)"},{"p":"wissen-kabinett-und-kanone.html","i":"i440","x":"IV Der Kanonenturm: ein Blick über die Stadt Wer im Turm auf „Mit Kanone schießen\" klickt, sieht die Stadt von oben aus dem Turm, mit der Kanone im Bild. Ein Ziel wählt man nicht aus einer Liste: Ihr zielt frei, indem Ihr die Maus zieht oder an den Rand fahrt. Oben zeigen drei Balken Wind, Winkel und den Zustand des Geschützes, dazu die Kosten des Schusses. Unten liegen die Knöpfe für einfaches, d"},{"p":"wissen-kabinett-und-kanone.html","i":"i441","x":"V Die Munition bestimmt das Kaliber Das Kaliber, das Ihr einstellen dürft, hängt allein an der besten Kugelart, die Ihr gekauft habt — eine Leiter: Kugelart Preis des Ausbaus höchstes Kaliber Burg Steinkugel 50 15 Pfünder ja Eisenkugel 400 20 Pfünder ja Schrappnell 600 25 Pfünder ja Hundert Pfünder 800 30 Pfünder ja Kartätsche 1.500 40 Pfünder — Das Pulver hat damit nichts zu tun. Daß der 40-Pfünd"},{"p":"wissen-kabinett-und-kanone.html","i":"i442","x":"VI Die Reichweite — und der Knallgasbehälter Die Treibladungen machen den Schuß nicht stärker, sondern weiter. So sagt es auch ihr Hilfetext. Gerechnet wird ein Reichweitenfaktor: gekauft Faktor nichts 1,00 Schwarzpulverladung (400) 1,05 dazu Langes Rohr (400) 1,10 dazu Melonitladung (800, nur Schloß) 1,15 Das Lange Rohr gehört also genau so zur Reichweite wie die Treibmittel. Ein Ausbau, der nich"},{"p":"wissen-kabinett-und-kanone.html","i":"i443","x":"VII Die Kanone rechnet mit Eisen und Schwerkraft Das Original rechnet den Schuß als echte Physik: mit dem Radius der Kugel in Metern, der Dichte von Eisen (7.874 kg/m³), der Erdbeschleunigung 9,81 und der Bewegungsenergie beim Aufschlag. Rechnet man aus den Radien die Massen aus, liegen sie nahe an den Namen der Kaliber: Kaliber Masse der Kugel in Pfund à 500 g 15 Pfünder 7,1 kg 14,2 20 Pfünder 9,"},{"p":"wissen-kabinett-und-kanone.html","i":"i444","x":"VIII Zielhilfen machen den Schuß ruhiger, nicht sicherer Kimme und Korn, Gezogener Lauf und Fadenkreuz geben keinen Zuschlag auf eine Trefferchance. Sie verkleinern die Streuung, mit der jede Kugel von ihrer Bahn abweicht: Zielhilfen Streuung in der Weite zur Seite keine ±20 % ±2 % alle drei ±10 % ±1 % Der Hilfetext sagt es selbst: Genauigkeit erspart Euch den „Haß von Unbeteiligten\". Es geht also"},{"p":"wissen-kabinett-und-kanone.html","i":"i445","x":"IX Was ein Schuß kostet Aktionspunkte: Kaliber + 2, also 2 bis 6. Gulden: (2 · Pulver + 500) · (1 + Kaliber/4) · Zahl der Kugeln. Das reicht von 500 Gulden (Steinkugel, kein Pulver, ein Rohr) bis 4.200 (Kartätsche, volles Pulver, drei Rohre). Der Ladenpreis der Kugel ist also nur der Preis, das Kaliber freizuschalten — jeder Schuß kostet danach nach Pulver und Größe. Dazu nutzt sich das Geschütz a"},{"p":"wissen-kabinett-und-kanone.html","i":"i446","x":"X Ein Treffer legt Feuer Beim Aufschlag sucht das Spiel bis zu drei Gebäude je Kugel, die nah genug liegen. Der Schaden ist die Wucht des Aufschlags, die mit der Entfernung abfällt, und reicht bis 100 — genau die Skala, auf der ein Haus seinen Zustand führt. wo die Kugel einschlägt was geschieht die Meldung neben dem Haus der Zustand des Hauses sinkt sofort um den Schaden leicht im Haus, Schaden b"},{"p":"wissen-kabinett-und-kanone.html","i":"i447","x":"XI Was offen ist ob ein Kanonenschuß durch göttlichen Segen abzuwehren ist, und wie daraus die Straftat entsteht, die das Stadtgesetz zum Kanonenturm kennt — nicht nachgelesen; welcher Wert hinter dem Windbalken steht — nicht nachgelesen; Erfolgsaussichten und Wirkungen der vier Kabinettsaufträge — nicht nachgelesen. Im Nachbau. Vom Kanonenturm ist die Bedienung des Originals noch nicht gebaut; da"}];
